const lessons = [
{"num": 2, "time": "00:00:30,000 --> 00:01:05,879", "arabic": "كُلُّ نَفْسٍ ذَائِقَةُ الْمَوْتِ، وَإِنَّمَا تُوَفَّوْنَ أُجُورَكُمْ يَوْمَ الْقِيَامَةِ، فَمَنْ زُحْزِحَ عَنِ النَّارِ وَأُدْخِلَ الْجَنَّةَ فَقَدْ فَازَ، وَمَا الْحَيَاةُ الدُّنْيَا إِلَّا مَتَاعُ الْغُرُورِ.", "segs": [{"ar": "كُلُّ نَفْسٍ ذَائِقَةُ الْمَوْتِ،", "uz": "Har bir jon o'limni totuvchidir."}, {"ar": "وَإِنَّمَا تُوَفَّوْنَ أُجُورَكُمْ يَوْمَ الْقِيَامَةِ،", "uz": "Sizlarga ajrlaringiz faqat Qiyomat kuni to'liq"}, {"ar": "فَمَنْ زُحْزِحَ عَنِ النَّارِ وَأُدْخِلَ الْجَنَّةَ فَقَدْ فَازَ،", "uz": "beriladi. Kim olovdan chetlashtirilib, Jannatga kiritilsa,"}, {"ar": "وَمَا الْحَيَاةُ الدُّنْيَا إِلَّا مَتَاعُ الْغُرُورِ.", "uz": "haqiqatan g'olib bo'ldi. Dunyo hayoti esa faqat aldanchi matohdan iboratdir."}], "full_uz": "Har bir jon o'limni totuvchidir. Sizlarga ajrlaringiz faqat Qiyomat kuni to'liq beriladi. Kim olovdan chetlashtirilib, Jannatga kiritilsa, haqiqatan g'olib bo'ldi. Dunyo hayoti esa faqat aldanchi matohdan iboratdir.", "note": "Qur'on, Oli Imron surasi, 185-oyat."},
{"num": 8, "time": "00:01:05,879 --> 00:01:30,760", "arabic": "أَيُّهَا الْمُسْلِمُونَ، أَحْسَنَ اللَّهُ عَزَاءَكُمْ فِي خَلِيفَتِكُمْ وَمَوْلَاكُمْ، اخْتَارَ اللَّهُ إِلَى جِوَارِهِ أَمِيرَ الْمُؤْمِنِينَ أَبَا إِسْحَاقَ الْمُعْتَصِمَ مُحَمَّدَ بْنَ هَارُونَ الرَّشِيدِ.", "segs": [{"ar": "أَيُّهَا الْمُسْلِمُونَ،", "uz": "Ey musulmonlar,"}, {"ar": "أَحْسَنَ اللَّهُ عَزَاءَكُمْ فِي خَلِيفَتِكُمْ وَمَوْلَاكُمْ،", "uz": "Alloh sizlarni xalifangiz va xo'jayiningizga bo'lgan tasalligingizni"}, {"ar": "اخْتَارَ اللَّهُ إِلَى جِوَارِهِ أَمِيرَ الْمُؤْمِنِينَ", "uz": "go'zal qilsin. Alloh mo'minlar amiri Abu Ishoq"}, {"ar": "أَبَا إِسْحَاقَ الْمُعْتَصِمَ مُحَمَّدَ بْنَ هَارُونَ الرَّشِيدِ.", "uz": "al-Mu'tasim Muhammad ibn Horun ar-Rashidni O'z huzuriga tanladi."}], "full_uz": "Ey musulmonlar, Alloh sizlarni xalifangiz va xo'jayiningizga bo'lgan tasalligingizni go'zal qilsin. Alloh mo'minlar amiri Abu Ishoq al-Mu'tasim Muhammad ibn Horun ar-Rashidni O'z huzuriga tanladi.", "note": null},
{"num": 15, "time": "00:01:30,760 --> 00:01:35,460", "arabic": "سَلُوا اللَّهَ الْمَغْفِرَةَ وَالرَّحْمَةَ لِأَمِيرِ الْمُؤْمِنِينَ.", "segs": null, "full_uz": "Mo'minlar amiri uchun Allohdan mag'firat va rahmat so'rang.", "note": null},
{"num": 16, "time": "00:01:35,460 --> 00:01:56,540", "arabic": "أَيُّهَا الْمُسْلِمُونَ، سَلُوا اللَّهَ الرَّحْمَةَ وَالْمَغْفِرَةَ لِمَوْلَاكُمْ، وَأَنْ يُسَدِّدَ اللَّهُ خُطَى خَلِيفَتِهِ ابْنِهِ أَمِيرِ الْمُؤْمِنِينَ هَارُونَ الْوَاثِقِ ابْنِ مُحَمَّدٍ الْمُعْتَصِمِ ابْنِ هَارُونَ الرَّشِيدِ.", "segs": [{"ar": "أَيُّهَا الْمُسْلِمُونَ،", "uz": "Ey musulmonlar,"}, {"ar": "سَلُوا اللَّهَ الرَّحْمَةَ وَالْمَغْفِرَةَ لِمَوْلَاكُمْ،", "uz": "xo'jayiningiz uchun Allohdan rahmat va mag'firat so'rang,"}, {"ar": "وَأَنْ يُسَدِّدَ اللَّهُ خُطَى خَلِيفَتِهِ ابْنِهِ أَمِيرِ الْمُؤْمِنِينَ", "uz": "va Alloh uning xalifasi bo'lgan o'g'li, mo'minlar amiri Horun al-Vosiq"}, {"ar": "هَارُونَ الْوَاثِقِ ابْنِ مُحَمَّدٍ الْمُعْتَصِمِ ابْنِ هَارُونَ الرَّشِيدِ.", "uz": "ibn Muhammad al-Mu'tasim ibn Horun ar-Rashidning qadamlarini to'g'rilasin deb so'rang."}], "full_uz": "Ey musulmonlar, xo'jayiningiz uchun Allohdan rahmat va mag'firat so'rang, va Alloh uning xalifasi bo'lgan o'g'li, mo'minlar amiri Horun al-Vosiq ibn Muhammad al-Mu'tasim ibn Horun ar-Rashidning qadamlarini to'g'rilasin deb so'rang.", "note": null},
{"num": 22, "time": "00:01:56,540 --> 00:02:01,880", "arabic": "صَلُّوا عَلَى النَّبِيِّ، لَا إِلَهَ إِلَّا اللَّهُ.", "segs": null, "full_uz": "Payg'ambarga salovat ayting, Allohdan boshqa iloh yo'q.", "note": null},
{"num": 24, "time": "00:02:01,880 --> 00:02:22,100", "arabic": "السَّلَامُ عَلَيْكُمْ.", "segs": null, "full_uz": "Assalomu alaykum.", "note": null},
{"num": 25, "time": "00:02:22,100 --> 00:02:24,120", "arabic": "وَعَلَيْكُمُ السَّلَامُ وَرَحْمَةُ اللَّهِ.", "segs": null, "full_uz": "Va alaykum assalomu va rahmatullah.", "note": null},
{"num": 26, "time": "00:02:24,120 --> 00:02:26,120", "arabic": "كَيْفَ حَالُكِ يَا خَالَةُ؟", "segs": null, "full_uz": "Ahvolingiz qalay, xolajon?", "note": null},
{"num": 27, "time": "00:02:26,539 --> 00:02:27,819", "arabic": "تَأَخَّرْتُمْ يَا صَالِحُ.", "segs": null, "full_uz": "Kechikdinglar, Solih.", "note": null},
{"num": 28, "time": "00:02:27,819 --> 00:02:36,979", "arabic": "لَوْ رَأَيْتِ يَا خَالَةُ كَثْرَةَ النَّاسِ الَّذِينَ خَرَجُوا فِي تَشْيِيعِ أَمِيرِ الْمُؤْمِنِينَ رَحِمَهُ اللَّهُ، لَقَدْ كَانَ يَوْمًا مَشْهُودًا.", "segs": [{"ar": "لَوْ رَأَيْتِ يَا خَالَةُ كَثْرَةَ النَّاسِ الَّذِينَ", "uz": "Mo'minlar amirini (Alloh unga rahmat qilsin) kuzatishga"}, {"ar": "خَرَجُوا فِي تَشْيِيعِ أَمِيرِ الْمُؤْمِنِينَ رَحِمَهُ اللَّهُ،", "uz": "chiqqan odamlarning ko'pligini ko'rsangiz edi, xolajon,"}, {"ar": "لَقَدْ كَانَ يَوْمًا مَشْهُودًا.", "uz": "bu unutilmas kun bo'ldi."}], "full_uz": "Mo'minlar amirini (Alloh unga rahmat qilsin) kuzatishga chiqqan odamlarning ko'pligini ko'rsangiz edi, xolajon, bu unutilmas kun bo'ldi.", "note": null},
{"num": 30, "time": "00:02:36,979 --> 00:02:41,139", "arabic": "رَحِمَهُ اللَّهُ وَغَفَرَ لَهُ.", "segs": null, "full_uz": "Alloh unga rahmat qilsin va mag'firat etsin.", "note": null},
{"num": 32, "time": "00:02:41,139 --> 00:02:46,079", "arabic": "مَنْ كَانَ عَلَى رَأْسِ التَّشْيِيعِ؟", "segs": null, "full_uz": "Kuzatuvda kim bosh bo'ldi?", "note": null},
{"num": 33, "time": "00:02:46,079 --> 00:03:00,960", "arabic": "ابْنُهُ هَارُونُ الْوَاثِقُ الَّذِي أَصْبَحَ أَمِيرَ الْمُؤْمِنِينَ بَعْدَ وَفَاةِ أَبِيهِ، وَابْنُهُ الْآخَرُ جَعْفَرٌ الْمُتَوَكِّلُ، وَالْحَاشِيَةُ الَّتِي يَرْأَسُهَا قَاضِي الْقُضَاةِ الْأَمِيرُ أَحْمَدُ بْنُ أَبِي دُؤَادٍ وَجَمَاعَتُهُ مِنَ الْمُعْتَزِلَةِ وَأَضْرَابُهُمْ.", "segs": [{"ar": "ابْنُهُ هَارُونُ الْوَاثِقُ الَّذِي أَصْبَحَ أَمِيرَ الْمُؤْمِنِينَ بَعْدَ وَفَاةِ أَبِيهِ،", "uz": "Otasi vafotidan keyin mo'minlar amiri bo'lgan o'g'li Horun al-Vosiq,"}, {"ar": "وَابْنُهُ الْآخَرُ جَعْفَرٌ الْمُتَوَكِّلُ،", "uz": "boshqa o'g'li Ja'far al-Mutavakkil,"}, {"ar": "وَالْحَاشِيَةُ الَّتِي يَرْأَسُهَا قَاضِي الْقُضَاةِ الْأَمِيرُ أَحْمَدُ بْنُ أَبِي دُؤَادٍ", "uz": "va boshliq qozi Amir Ahmad ibn Abi Du'od"}, {"ar": "وَجَمَاعَتُهُ مِنَ الْمُعْتَزِلَةِ وَأَضْرَابُهُمْ.", "uz": "hamda uning Mu'tazila jamoasi va ularga o'xshashlar boshchiligidagi saroy a'zolari."}], "full_uz": "Otasi vafotidan keyin mo'minlar amiri bo'lgan o'g'li Horun al-Vosiq, boshqa o'g'li Ja'far al-Mutavakkil, va boshliq qozi Amir Ahmad ibn Abi Du'od hamda uning Mu'tazila jamoasi va ularga o'xshashlar boshchiligidagi saroy a'zolari.", "note": null},
{"num": 36, "time": "00:03:00,960 --> 00:03:17,019", "arabic": "كَثِيرٌ مِنْ شُيُوخِنَا وَعُلَمَائِنَا يُفَكِّرُونَ بِمَا تُفَكِّرُ بِهِ يَا أَبِي، إِنَّهُمْ يَظُنُّونَ أَنَّ الْوَاثِقَ أَشْبَهُ بِعَمِّهِ الْمَأْمُونِ مِنْ أَبِيهِ الْمُعْتَصِمِ.", "segs": [{"ar": "كَثِيرٌ مِنْ شُيُوخِنَا", "uz": "Ko'p shayxlarimiz va"}, {"ar": "وَعُلَمَائِنَا يُفَكِّرُونَ بِمَا تُفَكِّرُ بِهِ يَا أَبِي،", "uz": "olimlarimiz siz o'ylagandek o'ylashadi, dadajon,"}, {"ar": "إِنَّهُمْ يَظُنُّونَ أَنَّ الْوَاثِقَ أَشْبَهُ", "uz": "ular Vosiq otasi Mu'tasimdan ko'ra"}, {"ar": "بِعَمِّهِ الْمَأْمُونِ مِنْ أَبِيهِ الْمُعْتَصِمِ.", "uz": "amakisi Ma'munga o'xshaydi deb hisoblashadi."}], "full_uz": "Ko'p shayxlarimiz va olimlarimiz siz o'ylagandek o'ylashadi, dadajon, ular Vosiq otasi Mu'tasimdan ko'ra amakisi Ma'munga o'xshaydi deb hisoblashadi.", "note": null},
{"num": 38, "time": "00:03:17,020 --> 00:03:25,100", "arabic": "بَلْ إِنَّ بَعْضَ مَنْ يَتَرَدَّدُونَ عَلَى الْقَصْرِ قَالُوا إِنَّ الْوَاثِقَ أَكْثَرُ تَشَدُّدًا مِنْ عَمِّهِ فِي مَسْأَلَةِ خَلْقِ الْقُرْآنِ.", "segs": [{"ar": "بَلْ إِنَّ بَعْضَ مَنْ يَتَرَدَّدُونَ عَلَى الْقَصْرِ", "uz": "Hatto saroyga tez-tez borib turadiganlarning ba'zilari"}, {"ar": "قَالُوا إِنَّ الْوَاثِقَ أَكْثَرُ تَشَدُّدًا مِنْ عَمِّهِ فِي مَسْأَلَةِ خَلْقِ الْقُرْآنِ.", "uz": "Vosiq Qur'onning yaratilganligi masalasida amakisidan ham qattiqqo'lroq ekanini aytishdi."}], "full_uz": "Hatto saroyga tez-tez borib turadiganlarning ba'zilari Vosiq Qur'onning yaratilganligi masalasida amakisidan ham qattiqqo'lroq ekanini aytishdi.", "note": null},
{"num": 40, "time": "00:03:25,100 --> 00:03:32,820", "arabic": "أَرْجُو أَنْ لَا تَكُونَ وَفَاةُ الْمُعْتَصِمِ رَحِمَهُ اللَّهُ قَدْ فَتَحَتْ عَلَيْنَا بَابَ الشَّرِّ ثَانِيَةً.", "segs": [{"ar": "أَرْجُو أَنْ لَا تَكُونَ وَفَاةُ الْمُعْتَصِمِ رَحِمَهُ اللَّهُ قَدْ", "uz": "Umid qilamanki, Mu'tasim (Alloh unga rahmat qilsin)ning vafoti yomonlik"}, {"ar": "فَتَحَتْ عَلَيْنَا بَابَ الشَّرِّ ثَانِيَةً.", "uz": "eshigini bizga yana ochmagan bo'lsin."}], "full_uz": "Umid qilamanki, Mu'tasim (Alloh unga rahmat qilsin)ning vafoti yomonlik eshigini bizga yana ochmagan bo'lsin.", "note": null},
{"num": 42, "time": "00:03:32,820 --> 00:03:36,300", "arabic": "النَّاسُ قَلِقُونَ فِي الْخَارِجِ يَا أَبِي.", "segs": null, "full_uz": "Tashqarida odamlar xavotirda, dadajon.", "note": null},
{"num": 43, "time": "00:03:43,180 --> 00:03:46,860", "arabic": "لَنْ يَقَعَ فِي مُلْكِ اللَّهِ إِلَّا مَا يُرِيدُ.", "segs": null, "full_uz": "Allohning mulkida faqat U xohlagan narsa bo'ladi.", "note": null},
{"num": 44, "time": "00:03:46,860 --> 00:03:56,920", "arabic": "يَا ابْنَ السِّرَاجِ.", "segs": null, "full_uz": "Ey Ibn Siroj.", "note": null},
{"num": 45, "time": "00:03:56,920 --> 00:04:14,140", "arabic": "كَيْفَ رَأَيْتَ قُلُوبَ عُلَمَاءِ بَغْدَادَ وَشُيُوخِهَا عَلَى أَمِيرِ الْمُؤْمِنِينَ الْوَاثِقِ حَفِظَهُ اللَّهُ وَرَعَاهُ؟", "segs": [{"ar": "كَيْفَ رَأَيْتَ قُلُوبَ عُلَمَاءِ بَغْدَادَ", "uz": "Bag'dod olimlari va shayxlarining qalbi mo'minlar amiri"}, {"ar": "وَشُيُوخِهَا عَلَى أَمِيرِ الْمُؤْمِنِينَ الْوَاثِقِ حَفِظَهُ اللَّهُ وَرَعَاهُ؟", "uz": "Vosiqqa (Alloh uni asrasin va parvarish qilsin) nisbatan qanday deb ko'rdingiz?"}], "full_uz": "Bag'dod olimlari va shayxlarining qalbi mo'minlar amiri Vosiqqa (Alloh uni asrasin va parvarish qilsin) nisbatan qanday deb ko'rdingiz?", "note": null},
{"num": 48, "time": "00:04:14,140 --> 00:04:27,879", "arabic": "الْحَقُّ يَا مَوْلَايَ أَنَّهُمْ قَلِقُونَ، تُسَاوِرُهُمُ الشُّكُوكُ، وَهُمْ يَرَوْنَ أَنَّ أَمِيرَ الْمُؤْمِنِينَ الْوَاثِقَ أَكْثَرُ تَشَدُّدًا مِنْ عَمِّهِ الْمَأْمُونِ رَحِمَهُ اللَّهُ فِي مَسْأَلَةِ خَلْقِ الْقُرْآنِ.", "segs": [{"ar": "الْحَقُّ يَا مَوْلَايَ أَنَّهُمْ قَلِقُونَ، تُسَاوِرُهُمُ الشُّكُوكُ،", "uz": "Rostini aytsam, xo'jayinim, ular xavotirda, shubhalar ularni o'rab olgan,"}, {"ar": "وَهُمْ يَرَوْنَ أَنَّ أَمِيرَ الْمُؤْمِنِينَ الْوَاثِقَ أَكْثَرُ تَشَدُّدًا مِنْ عَمِّهِ الْمَأْمُونِ رَحِمَهُ اللَّهُ", "uz": "va ular mo'minlar amiri Vosiqni amakisi Ma'mun (Alloh unga rahmat qilsin)dan ham qattiqqo'lroq deb bilishadi,"}, {"ar": "فِي مَسْأَلَةِ خَلْقِ الْقُرْآنِ.", "uz": "Qur'onning yaratilganligi masalasida."}], "full_uz": "Rostini aytsam, xo'jayinim, ular xavotirda, shubhalar ularni o'rab olgan, va ular mo'minlar amiri Vosiqni bu masalada amakisi Ma'mun (Alloh unga rahmat qilsin)dan ham qattiqqo'lroq deb bilishadi.", "note": null},
{"num": 54, "time": "00:04:27,879 --> 00:04:33,379", "arabic": "اغْفِرْ لِي أَنِّي أَسْتَخْدِمُ مَا يَصْطَلِحُونَ عَلَيْهِ يَا مَوْلَايَ.", "segs": null, "full_uz": "Ularning o'z atamalarini ishlatganim uchun meni kechiring, xo'jayinim.", "note": null},
{"num": 55, "time": "00:04:33,379 --> 00:04:50,819", "arabic": "لَا عَلَيْكَ يَا ابْنَ السِّرَاجِ.", "segs": null, "full_uz": "Hech gap emas, Ibn Siroj.", "note": null},
{"num": 57, "time": "00:04:50,819 --> 00:04:59,279", "arabic": "سَيَرَوْنَ مَا يُثْبِتُ شُكُوكَهُمْ وَقَلَقَهُمْ.", "segs": null, "full_uz": "Ular o'z shubha va xavotirlarini isbotlaydigan narsani ko'rishadi.", "note": null},
{"num": 58, "time": "00:04:59,279 --> 00:05:02,779", "arabic": "مَاذَا تَقْصِدُ يَا مَوْلَايَ؟", "segs": null, "full_uz": "Nimani nazarda tutyapsiz, xo'jayinim?", "note": null},
{"num": 59, "time": "00:05:04,779 --> 00:05:14,899", "arabic": "أَقْصِدُ أَنَّ عَهْدَ الطُّمَأْنِينَةِ الَّتِي عَرَفُوهَا فِي عَهْدِ الْمُعْتَصِمِ قَدْ وَلَّى إِلَى غَيْرِ رَجْعَةٍ.", "segs": [{"ar": "أَقْصِدُ أَنَّ عَهْدَ الطُّمَأْنِينَةِ الَّتِي عَرَفُوهَا فِي عَهْدِ الْمُعْتَصِمِ قَدْ", "uz": "Nazarda tutyapmanki, Mu'tasim davrida bilgan xotirjamlik davri qaytmaslik"}, {"ar": "وَلَّى إِلَى غَيْرِ رَجْعَةٍ.", "uz": "uchun o'tib ketdi."}], "full_uz": "Nazarda tutyapmanki, Mu'tasim davrida bilgan xotirjamlik davri qaytmaslik uchun o'tib ketdi.", "note": null},
{"num": 61, "time": "00:05:14,899 --> 00:05:19,799", "arabic": "إِذَنْ فَلْتَخْشَ عُلَمَاءُ بَغْدَادَ عَلَى مَكَانَتِهَا.", "segs": null, "full_uz": "Unda Bag'dod olimlari o'z mavqeidan qo'rqsinlar.", "note": null},
{"num": 62, "time": "00:05:19,799 --> 00:05:23,739", "arabic": "سَيَرَوْنَ مَا لَمْ يَخْطُرْ عَلَى بَالِهِمْ يَوْمًا.", "segs": null, "full_uz": "Ular hech qachon xayollariga kelmagan narsani ko'rishadi.", "note": null},
{"num": 63, "time": "00:05:23,739 --> 00:05:57,960", "arabic": "وَلِمَ لَا؟ وَالدَّوْلَةُ الْآنَ أَصْبَحَتْ فِي قَبْضَتِنَا أَكْثَرَ مِنْ قَبْلُ، وَحَمَاسُ أَمِيرِ الْمُؤْمِنِينَ حَفِظَهُ اللَّهُ وَرَعَاهُ أَشَدُّ مِنْ حَمَاسِنَا لِلْحَقِّ فِي مَسْأَلَةِ خَلْقِ الْقُرْآنِ، وَإِنْكَارِ التَّجْسِيمِ الَّذِي وَلِعَ بِهِ الْمُتَجَسِّمُونَ ظُلْمًا وَبُهْتَانًا، عُلَمَاءُ أَهْلِ السُّنَّةِ وَالْجَمَاعَةِ.", "segs": [{"ar": "وَلِمَ لَا؟ وَالدَّوْلَةُ الْآنَ أَصْبَحَتْ فِي قَبْضَتِنَا أَكْثَرَ مِنْ قَبْلُ،", "uz": "Nega bo'lmasin? Davlat endi ilgarigidan ko'ra ko'proq bizning qo'limizda,"}, {"ar": "وَحَمَاسُ أَمِيرِ الْمُؤْمِنِينَ حَفِظَهُ اللَّهُ وَرَعَاهُ أَشَدُّ مِنْ حَمَاسِنَا لِلْحَقِّ فِي مَسْأَلَةِ خَلْقِ الْقُرْآنِ،", "uz": "va mo'minlar amirining shijoati Qur'onning yaratilganligi masalasida bizning shijoatimizdan ham kuchliroq,"}, {"ar": "وَإِنْكَارِ التَّجْسِيمِ الَّذِي وَلِعَ بِهِ الْمُتَجَسِّمُونَ ظُلْمًا وَبُهْتَانًا،", "uz": "va zulm hamda tuhmat bilan jismlantiruvchilar moyil bo'lgan tajassumni rad etishda ham,"}, {"ar": "عُلَمَاءُ أَهْلِ السُّنَّةِ وَالْجَمَاعَةِ.", "uz": "ya'ni ahli sunna va jamoat olimlarini."}], "full_uz": "Nega bo'lmasin? Davlat endi ilgarigidan ko'ra ko'proq bizning qo'limizda, va mo'minlar amirining (Alloh uni asrasin) shijoati Qur'onning yaratilganligi va zulm hamda tuhmat bilan jismlantiruvchilar — ya'ni ahli sunna va jamoat olimlari — moyil bo'lgan tajassum (Allohni jismga o'xshatish)ni rad etish masalasida haqqa bo'lgan bizning shijoatimizdan ham kuchliroq.", "note": null},
{"num": 69, "time": "00:05:57,960 --> 00:06:05,840", "arabic": "إِذَنْ فَقَدْ عَقَدْتَ الْعَزْمَ.", "segs": null, "full_uz": "Unda azm qilibsiz.", "note": null},
{"num": 71, "time": "00:06:12,860 --> 00:06:27,860", "arabic": "أُقْسِمُ، أُقْسِمُ سَيَكُونُ ثَمَنُ ضَلَالِهِمْ بَاهِظًا، وَلَأَضْرِبَنَّ سَادَتَهُمْ حَتَّى يَخَافَ أَتْبَاعُهُمْ مِنَ الْغَوْغَاءِ وَالْعَامَّةِ.", "segs": [{"ar": "أُقْسِمُ، أُقْسِمُ سَيَكُونُ ثَمَنُ ضَلَالِهِمْ بَاهِظًا،", "uz": "Qasam ichaman, qasam ichamanki, ularning adashuvining narxi qimmat bo'ladi,"}, {"ar": "وَلَأَضْرِبَنَّ سَادَتَهُمْ حَتَّى يَخَافَ أَتْبَاعُهُمْ مِنَ الْغَوْغَاءِ وَالْعَامَّةِ.", "uz": "va ularning ustalarini shunday urib qo'yamanki, izdoshlari va omma qo'rqib qolsin."}], "full_uz": "Qasam ichaman, qasam ichamanki, ularning adashuvining narxi qimmat bo'ladi, va ularning ustalarini shunday urib qo'yamanki, izdoshlari va omma qo'rqib qolsin.", "note": null},
{"num": 75, "time": "00:06:28,860 --> 00:06:34,860", "arabic": "كَمْ أَتَحَرَّقُ شَوْقًا لِرُؤْيَةِ أَنْفِ كَبِيرِهِمْ يُمَرَّغُ فِي التُّرَابِ.", "segs": null, "full_uz": "Ularning kattasining burni tuproqqa ishqalanganini ko'rishga naqadar ishtiyoq bilan yonaman.", "note": null},
{"num": 76, "time": "00:06:37,860 --> 00:06:41,860", "arabic": "أَتَقْصِدُ أَحْمَدَ بْنَ حَنْبَلٍ؟", "segs": null, "full_uz": "Ahmad ibn Hanbalni nazarda tutyapsizmi?", "note": null},
{"num": 78, "time": "00:06:42,860 --> 00:06:52,759", "arabic": "ابْنُ حَنْبَلٍ، أَوَّلُ مَنْ سَأَبْدَأُ بِهِ.", "segs": null, "full_uz": "Ibn Hanbal — men boshlaydigan birinchi kishi.", "note": null},
{"num": 80, "time": "00:06:52,759 --> 00:07:14,060", "arabic": "لَقَدْ كَانَ مَا حَدَثَ انْتِصَارًا لِلْبَاطِلِ عَلَى الْحَقِّ يَا مَوْلَايَ، وَلَوْلَا شَفَقَةُ أَمِيرِ الْمُؤْمِنِينَ رَحِمَهُ اللَّهُ لَمَا كَانَ لِظَالِمٍ مِثْلِهِ إِلَّا مَصِيرٌ يَلِيقُ بِأَمْثَالِهِ.", "segs": [{"ar": "لَقَدْ كَانَ مَا حَدَثَ انْتِصَارًا", "uz": "Bo'lgan voqea botilning haq ustidan g'alabasi bo'ldi,"}, {"ar": "لِلْبَاطِلِ عَلَى الْحَقِّ يَا مَوْلَايَ،", "uz": "xo'jayinim, va agar mo'minlar amiri"}, {"ar": "وَلَوْلَا شَفَقَةُ أَمِيرِ الْمُؤْمِنِينَ رَحِمَهُ اللَّهُ لَمَا", "uz": "(Alloh unga rahmat qilsin)ning shafqati bo'lmaganida,"}, {"ar": "كَانَ لِظَالِمٍ مِثْلِهِ إِلَّا مَصِيرٌ يَلِيقُ بِأَمْثَالِهِ.", "uz": "unga o'xshash zolimga faqat o'ziga munosib bir yakun bo'lardi."}], "full_uz": "Bo'lgan voqea botilning haq ustidan g'alabasi bo'ldi, xo'jayinim, va agar mo'minlar amiri (Alloh unga rahmat qilsin)ning shafqati bo'lmaganida, unga o'xshash zolimga faqat o'ziga munosib bir yakun bo'lardi.", "note": null},
{"num": 83, "time": "00:07:14,060 --> 00:07:28,399", "arabic": "إِنَّنِي أَكْثَرُ غَيْظًا مِنْكَ يَا ابْنَ أَبِي دُؤَادٍ، وَكُلَّمَا تَذَكَّرْتُ مَا حَدَثَ تَمَنَّيْتُ لَوْ أَنَّنِي جَلَدْتُهُ بِيَدِي حَتَّى لَا يَخْرُجَ مِنْ بَيْنِنَا وَكَأَنَّهُ قَدْ هَزَمَنَا جَمِيعًا.", "segs": [{"ar": "إِنَّنِي أَكْثَرُ غَيْظًا مِنْكَ", "uz": "Men sendan ham ko'proq g'azabdaman,"}, {"ar": "يَا ابْنَ أَبِي دُؤَادٍ،", "uz": "ey Ibn Abi Du'od,"}, {"ar": "وَكُلَّمَا تَذَكَّرْتُ مَا حَدَثَ تَمَنَّيْتُ لَوْ أَنَّنِي", "uz": "va bo'lgan voqeani eslar ekanman, uni o'z qo'lim bilan qamchilagan bo'lsam edi,"}, {"ar": "جَلَدْتُهُ بِيَدِي حَتَّى لَا يَخْرُجَ مِنْ بَيْنِنَا", "uz": "toki u orangizdan xuddi hammamizni yengib chiqqandek chiqmasin,"}, {"ar": "وَكَأَنَّهُ قَدْ هَزَمَنَا جَمِيعًا.", "uz": "deb orzu qildim."}], "full_uz": "Men sendan ham ko'proq g'azabdaman, ey Ibn Abi Du'od, va bo'lgan voqeani eslar ekanman, uni o'z qo'lim bilan qamchilagan bo'lsam edi, toki u orangizdan xuddi hammamizni yengib chiqqandek chiqmasin, deb orzu qildim.", "note": null},
{"num": 87, "time": "00:07:28,399 --> 00:07:45,020", "arabic": "لِذَلِكَ يَا مَوْلَايَ، هَذَا هُوَ الْوَقْتُ الْمُنَاسِبُ لِلتَّفَرُّغِ لِأَحْمَدَ بْنِ حَنْبَلٍ وَأَمْثَالِهِ، وَكَفِّ مَا قَضَوْهُ مِنْ غَوَايَةٍ وَتَضْلِيلٍ.", "segs": [{"ar": "لِذَلِكَ يَا مَوْلَايَ،", "uz": "Shuning uchun, xo'jayinim,"}, {"ar": "هَذَا هُوَ الْوَقْتُ الْمُنَاسِبُ لِلتَّفَرُّغِ لِأَحْمَدَ بْنِ حَنْبَلٍ وَأَمْثَالِهِ،", "uz": "bu Ahmad ibn Hanbal va uning o'xshashlariga bag'ishlanadigan mos vaqtdir,"}, {"ar": "وَكَفِّ مَا قَضَوْهُ مِنْ غَوَايَةٍ وَتَضْلِيلٍ.", "uz": "ularning adashtirish va yo'ldan ozdirishini to'xtatish uchun."}], "full_uz": "Shuning uchun, xo'jayinim, bu Ahmad ibn Hanbal va uning o'xshashlariga bag'ishlanadigan mos vaqtdir, ularning adashtirish va yo'ldan ozdirishini to'xtatish uchun.", "note": null},
{"num": 90, "time": "00:07:45,020 --> 00:07:56,000", "arabic": "أَتَرَى ذَلِكَ؟", "segs": null, "full_uz": "Shundaymi deb bilasizmi?", "note": null},
{"num": 92, "time": "00:08:02,160 --> 00:08:10,580", "arabic": "يَبْدُو أَنَّ خَالَتَكِ لَيْسَتْ عَلَى مَا يُرَامُ يَا سُعَادُ.", "segs": null, "full_uz": "Ko'rinishidan, xolangiz yaxshi ahvolda emas, Su'od.", "note": null},
{"num": 93, "time": "00:08:10,580 --> 00:08:15,520", "arabic": "إِنَّهَا لَمْ تَتَعَافَ مِنْ مَرَضِهَا مُنْذُ اسْتِشْهَادِ زَوْجِهَا رَحِمَهُ اللَّهُ.", "segs": [{"ar": "إِنَّهَا لَمْ تَتَعَافَ مِنْ مَرَضِهَا", "uz": "U eri (Alloh unga rahmat qilsin)"}, {"ar": "مُنْذُ اسْتِشْهَادِ زَوْجِهَا رَحِمَهُ اللَّهُ.", "uz": "shahid bo'lganidan beri o'z kasalidan tuzalmadi."}], "full_uz": "U eri (Alloh unga rahmat qilsin) shahid bo'lganidan beri o'z kasalidan tuzalmadi.", "note": null},
{"num": 94, "time": "00:08:15,520 --> 00:08:20,840", "arabic": "أَرَى أَنَّ الْمَرَضَ شَدِيدُ الْوَطْأَةِ عَلَيْهَا هَذِهِ الْمَرَّةَ.", "segs": null, "full_uz": "Bu safar kasallik unga qattiq ta'sir qilganini ko'ryapman.", "note": null},
{"num": 95, "time": "00:08:20,840 --> 00:08:25,180", "arabic": "كَانَ اللَّهُ فِي عَوْنِهَا، وَاهًا لِنَفْسِي.", "segs": null, "full_uz": "Alloh unga yordamchi bo'lsin, voy holimga.", "note": null},
{"num": 97, "time": "00:08:25,180 --> 00:08:31,879", "arabic": "يَبْدُو أَنَّ الْأَطِبَّاءَ عَاجِزُونَ عَنْ إِيجَادِ دَوَاءٍ لِعِلَاجِهَا.", "segs": null, "full_uz": "Ko'rinishidan, tabiblar unga davo topa olmayaptilar.", "note": null},
{"num": 98, "time": "00:08:31,879 --> 00:08:37,919", "arabic": "حَتَّى الْآنَ رَآهَا عَشَرَةُ أَطِبَّاءَ وَلَمْ يُفِيدُوهَا بِشَيْءٍ.", "segs": null, "full_uz": "Hozirgacha o'nta tabib uni ko'rdi, lekin hech biri foyda bermadi.", "note": null},
{"num": 99, "time": "00:08:37,919 --> 00:08:41,100", "arabic": "لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ.", "segs": null, "full_uz": "Kuch-quvvat faqat Allohdandir.", "note": null},
{"num": 100, "time": "00:08:41,100 --> 00:08:54,600", "arabic": "أَخْبَرْتُ أَبَاكِ أَنِّي سَأَبْقَى بِرِفْقَتِهَا لِأَقُومَ عَلَى خِدْمَتِهَا وَإِيناسِهَا، وَمَرَرْتُ عَلَيْكِ حَتَّى تُرَافِقِينِي لِزِيَارَتِهَا، فَهِيَ تَرْغَبُ أَنْ تَرَاكِ.", "segs": [{"ar": "أَخْبَرْتُ أَبَاكِ أَنِّي سَأَبْقَى بِرِفْقَتِهَا لِأَقُومَ عَلَى خِدْمَتِهَا وَإِيناسِهَا،", "uz": "Otangizga uning yonida qolib, unga xizmat qilib, ko'nglini ko'tarishimni aytdim,"}, {"ar": "وَمَرَرْتُ عَلَيْكِ حَتَّى تُرَافِقِينِي لِزِيَارَتِهَا،", "uz": "va sizni ziyoratiga hamrohlik qilishingiz uchun yo'lda oldingizga kirdim,"}, {"ar": "فَهِيَ تَرْغَبُ أَنْ تَرَاكِ.", "uz": "chunki u sizni ko'rishni istaydi."}], "full_uz": "Otangizga uning yonida qolib, unga xizmat qilib, ko'nglini ko'tarishimni aytdim, va sizni ziyoratiga hamrohlik qilishingiz uchun yo'lda oldingizga kirdim, chunki u sizni ko'rishni istaydi.", "note": null},
{"num": 103, "time": "00:08:54,600 --> 00:08:56,039", "arabic": "حَسَنًا.", "segs": null, "full_uz": "Xo'p bo'ladi.", "note": null},
{"num": 104, "time": "00:08:56,039 --> 00:09:01,200", "arabic": "هَيَّا قُومِي جَهِّزِي نَفْسَكِ، لَا أُرِيدُ أَنْ أَتَأَخَّرَ عَلَيْهَا.", "segs": null, "full_uz": "Yur, tur, tayyorlan, unga kechikishni istamayman.", "note": null},
{"num": 106, "time": "00:09:01,200 --> 00:09:05,940", "arabic": "سَأُخْبِرُ عَمَّتِي سَلْمَةَ أَوَّلًا حَتَّى تُرْسِلَ عَمْرَةَ فِي إِثْرِي تُعِيدُنِي إِلَى الْبَيْتِ.", "segs": [{"ar": "سَأُخْبِرُ عَمَّتِي سَلْمَةَ أَوَّلًا حَتَّى تُرْسِلَ", "uz": "Avval xolam Salamaga aytib qo'yaman,"}, {"ar": "عَمْرَةَ فِي إِثْرِي تُعِيدُنِي إِلَى الْبَيْتِ.", "uz": "u meni uyga qaytarish uchun Amrani orqamdan yuboradi."}], "full_uz": "Avval xolam Salamaga aytib qo'yaman, u meni uyga qaytarish uchun Amrani orqamdan yuboradi.", "note": null},
{"num": 107, "time": "00:09:05,940 --> 00:09:07,560", "arabic": "حَسَنًا تَفْعَلِينَ.", "segs": null, "full_uz": "Yaxshi qilyapsan.", "note": null},
{"num": 108, "time": "00:09:31,200 --> 00:09:47,600", "arabic": "السَّلَامُ عَلَيْكُمْ.", "segs": null, "full_uz": "Assalomu alaykum.", "note": null},
{"num": 110, "time": "00:09:47,600 --> 00:09:52,680", "arabic": "أَحْمَدُ بْنُ حَنْبَلٍ الشَّيْبَانِيُّ؟ هَذَا كِتَابُ أَمِيرِ الْمُؤْمِنِينَ إِلَيْكَ.", "segs": null, "full_uz": "Ahmad ibn Hanbal ash-Shayboniymisiz? Mana bu mo'minlar amirining sizga yo'llagan xati.", "note": null},
{"num": 112, "time": "00:10:01,200 --> 00:10:16,520", "arabic": "مَنْ كَانَ فِي الْبَابِ؟", "segs": null, "full_uz": "Eshikda kim bor edi?", "note": null},
{"num": 113, "time": "00:10:16,520 --> 00:10:18,200", "arabic": "رَسُولُ أَمِيرِ الْمُؤْمِنِينَ.", "segs": null, "full_uz": "Mo'minlar amirining elchisi.", "note": null},
{"num": 114, "time": "00:10:18,200 --> 00:10:23,660", "arabic": "وَمَا الَّذِي يُرِيدُهُ أَمِيرُ الْمُؤْمِنِينَ مِنْكَ يَا أَبَا عَبْدِ اللَّهِ؟", "segs": [{"ar": "وَمَا الَّذِي يُرِيدُهُ أَمِيرُ الْمُؤْمِنِينَ", "uz": "Mo'minlar amiri sizdan nima istaydi,"}, {"ar": "مِنْكَ يَا أَبَا عَبْدِ اللَّهِ؟", "uz": "ey Abu Abdulloh?"}], "full_uz": "Mo'minlar amiri sizdan nima istaydi, ey Abu Abdulloh?", "note": null},
{"num": 115, "time": "00:10:23,660 --> 00:10:29,200", "arabic": "لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ، الْعِلْمُ عِنْدَ اللَّهِ يَا رَيْحَانَةُ.", "segs": [{"ar": "لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ،", "uz": "Kuch-quvvat faqat Allohdandir,"}, {"ar": "الْعِلْمُ عِنْدَ اللَّهِ يَا رَيْحَانَةُ.", "uz": "ilm Allohning huzuridadir, ey Rayhona."}], "full_uz": "Kuch-quvvat faqat Allohdandir, ilm Allohning huzuridadir, ey Rayhona.", "note": null},
{"num": 117, "time": "00:10:31,200 --> 00:11:11,419", "arabic": "مَا الَّذِي يُرِيدُونَهُ مِنْكَ؟ قَاتَلَهُمُ اللَّهُ، أَلَا يَكْفِي مَا فَعَلُوهُ بِكَ سَابِقًا؟ أَلَيْسَ لِهَذَا اللَّيْلِ مِنْ آخِرٍ؟ أَلَيْسَ لَدَيْهِمْ مَا يَفْعَلُونَهُ سِوَى إِيذَاءِ عِبَادِ اللَّهِ؟", "segs": [{"ar": "مَا الَّذِي يُرِيدُونَهُ مِنْكَ؟ قَاتَلَهُمُ اللَّهُ،", "uz": "Sizdan nima istashadi? Alloh ularni halok qilsin,"}, {"ar": "أَلَا يَكْفِي مَا فَعَلُوهُ بِكَ سَابِقًا؟", "uz": "ilgari sizga qilgan ishlari yetarli emasmidi?"}, {"ar": "أَلَيْسَ لِهَذَا اللَّيْلِ مِنْ آخِرٍ؟", "uz": "Bu tunning oxiri yo'qmi?"}, {"ar": "أَلَيْسَ لَدَيْهِمْ مَا يَفْعَلُونَهُ سِوَى إِيذَاءِ عِبَادِ اللَّهِ؟", "uz": "Ularda Allohning bandalarini ozorlashdan boshqa qiladigan ishlari yo'qmi?"}], "full_uz": "Sizdan nima istashadi? Alloh ularni halok qilsin. Ilgari sizga qilgan ishlari yetarli emasmidi? Bu tunning oxiri yo'qmi? Ularda Allohning bandalarini ozorlashdan boshqa qiladigan ishlari yo'qmi?", "note": null},
{"num": 121, "time": "00:11:11,419 --> 00:11:27,519", "arabic": "لَمْ يَعُدْ لَهَا رَغْبَةٌ فِي الْحَيَاةِ مَعَنَا، حَتَّى أَخْشَى خَسَارَتَهَا.", "segs": [{"ar": "لَمْ يَعُدْ لَهَا رَغْبَةٌ فِي الْحَيَاةِ مَعَنَا،", "uz": "Uning endi biz bilan yashashga ishtiyoqi qolmadi,"}, {"ar": "حَتَّى أَخْشَى خَسَارَتَهَا.", "uz": "hatto uni yo'qotishdan qo'rqaman."}], "full_uz": "Uning endi biz bilan yashashga ishtiyoqi qolmadi, hatto uni yo'qotishdan qo'rqaman.", "note": null},
{"num": 123, "time": "00:11:27,519 --> 00:11:34,519", "arabic": "لِمَاذَا تُتْعِبُونَ أَنْفُسَكُمْ بِالرَّكْضِ خَلْفَ الْأَطِبَّاءِ؟", "segs": null, "full_uz": "Nega o'zingizni tabiblar ortidan yugurish bilan charchatasiz?", "note": null},
{"num": 124, "time": "00:11:36,519 --> 00:11:56,299", "arabic": "مُنْذُ سِنِينَ وَأَنَا أَبْحَثُ عَنِ الْمَوْتِ فِي كُلِّ أَلَمٍ أَوْ تَعَبٍ أَوْ مَرَضٍ، لَكِنَّهُ يَتَمَنَّعُ عَلَيَّ.", "segs": [{"ar": "مُنْذُ سِنِينَ", "uz": "Yillardan beri har bir og'riq,"}, {"ar": "وَأَنَا أَبْحَثُ عَنِ الْمَوْتِ فِي كُلِّ أَلَمٍ أَوْ تَعَبٍ أَوْ مَرَضٍ،", "uz": "charchoq yoki kasallikda o'limni izlab kelaman,"}, {"ar": "لَكِنَّهُ يَتَمَنَّعُ عَلَيَّ.", "uz": "lekin u mendan bosh tortadi."}], "full_uz": "Yillardan beri har bir og'riq, charchoq yoki kasallikda o'limni izlab kelaman, lekin u mendan bosh tortadi.", "note": null},
{"num": 127, "time": "00:11:57,519 --> 00:11:59,519", "arabic": "فِي ذَاتِ نَفْسِي يَا خَالِدُ.", "segs": null, "full_uz": "Ichimda o'ylaymanki, ey Xolid.", "note": null},
{"num": 128, "time": "00:12:01,519 --> 00:12:10,519", "arabic": "سَلَّمَكِ اللَّهُ يَا أُمِّي، غَفَرَ اللَّهُ لَكِ يَا أُخْتِي.", "segs": null, "full_uz": "Alloh sizni omon saqlasin, onajon, Alloh sizni mag'firat qilsin, opajon.", "note": null},
{"num": 130, "time": "00:12:12,519 --> 00:12:17,519", "arabic": "وَلَا تَقُولِي إِلَّا مَا يُرْضِيهِ.", "segs": null, "full_uz": "Va faqat Uni rozi qiladigan narsani ayting.", "note": null},
{"num": 132, "time": "00:12:18,519 --> 00:12:20,519", "arabic": "إِنَّكِ تُرْعِبِينَ بِكَلَامِكِ هَذَا يَا خَالَتَاهُ.", "segs": null, "full_uz": "Siz bu gapingiz bilan meni qo'rqityapsiz, ey xolajonim.", "note": null},
{"num": 133, "time": "00:12:23,519 --> 00:12:39,980", "arabic": "كُنْتُ فِي حَيَاتِهِ أَخْشَى الْمَوْتَ عَلَى نَفْسِي، فَلَمَّا رَحَلَ صِرْتُ أَخْشَى الْحَيَاةَ.", "segs": [{"ar": "كُنْتُ فِي حَيَاتِهِ أَخْشَى الْمَوْتَ عَلَى نَفْسِي،", "uz": "Uning hayotligida o'zim uchun o'limdan qo'rqar edim,"}, {"ar": "فَلَمَّا رَحَلَ صِرْتُ أَخْشَى الْحَيَاةَ.", "uz": "u vafot etganidan keyin esa hayotdan qo'rqadigan bo'ldim."}], "full_uz": "Uning hayotligida o'zim uchun o'limdan qo'rqar edim, u vafot etganidan keyin esa hayotdan qo'rqadigan bo'ldim.", "note": null},
{"num": 137, "time": "00:12:39,980 --> 00:13:02,060", "arabic": "كَانَ أَبُو صَخْرٍ الْهُذَلِيُّ حِينَ يَقُولُ: عَجِبْتُ لِسَعْيِ الدَّهْرِ بَيْنِي وَبَيْنَهَا، فَلَمَّا انْقَضَى مَا بَيْنَنَا سَكَنَ.", "segs": [{"ar": "كَانَ أَبُو صَخْرٍ الْهُذَلِيُّ حِينَ يَقُولُ: عَجِبْتُ لِسَعْيِ الدَّهْرِ بَيْنِي", "uz": "Abu Sakhr al-Huzaliy aytganidek: \"Men va u orasida zamonning harakatidan hayron bo'ldim,"}, {"ar": "وَبَيْنَهَا،", "uz": "ammo"}, {"ar": "فَلَمَّا انْقَضَى مَا بَيْنَنَا سَكَنَ.", "uz": "bizning orada bo'lgan narsa tugagach, u tinchidi.\""}], "full_uz": "Abu Sakhr al-Huzaliy aytganidek: \"Men va u orasida zamonning harakatidan hayron bo'ldim, ammo bizning orada bo'lgan narsa tugagach, u tinchidi.\"", "note": "Abu Sakhr al-Huzaliy (arab shoiri, islomdan avvalgi/umaviylar davri)ning mashhur she'riy baytiga ishora."},
{"num": 142, "time": "00:13:02,060 --> 00:13:12,000", "arabic": "فِي ذَاتِ نَفْسِي يَا خَالِدُ.", "segs": null, "full_uz": "Ichimda o'ylaymanki, ey Xolid.", "note": null},
{"num": 143, "time": "00:13:23,340 --> 00:13:41,780", "arabic": "كَلَامُ أَمِيرِ الْمُؤْمِنِينَ هَذِهِ الْمَرَّةَ وَاضِحٌ وَشَدِيدُ اللَّهْجَةِ وَلَا يَحْتَمِلُ التَّأْوِيلَ، قَالَ لِي: لَا تُسَاكِنِّي فِي أَرْضٍ وَلَا مَدِينَةٍ أَنَا فِيهَا، يَجِبُ أَنْ أَخْرُجَ مِنْ بَغْدَادَ.", "segs": [{"ar": "كَلَامُ أَمِيرِ الْمُؤْمِنِينَ هَذِهِ الْمَرَّةَ", "uz": "Mo'minlar amirining bu safargi gapi"}, {"ar": "وَاضِحٌ وَشَدِيدُ اللَّهْجَةِ وَلَا يَحْتَمِلُ التَّأْوِيلَ،", "uz": "aniq va qattiq ohangda bo'lib,"}, {"ar": "قَالَ لِي: لَا تُسَاكِنِّي فِي أَرْضٍ", "uz": "boshqa talqinni ko'tarmaydi. U menga: \"Men bo'lgan"}, {"ar": "وَلَا مَدِينَةٍ أَنَا فِيهَا،", "uz": "yer yoki shaharda men"}, {"ar": "يَجِبُ أَنْ أَخْرُجَ مِنْ بَغْدَادَ.", "uz": "bilan birga yashama\" dedi. Bag'doddan chiqishim shart."}], "full_uz": "Mo'minlar amirining bu safargi gapi aniq va qattiq ohangda bo'lib, boshqa talqinni ko'tarmaydi. U menga: \"Men bo'lgan yer yoki shaharda men bilan birga yashama\" dedi. Bag'doddan chiqishim shart.", "note": null},
{"num": 147, "time": "00:13:41,780 --> 00:13:45,420", "arabic": "إِذَنْ لَا حَلَّ إِلَّا مَا قَضَى بِهِ الْوَاثِقُ.", "segs": null, "full_uz": "Unda Vosiq hukm qilgan narsadan boshqa yechim yo'q.", "note": null},
{"num": 148, "time": "00:13:45,420 --> 00:13:49,200", "arabic": "سَتَبْقَى نَارُ الْفِتَنِ مُشْتَعِلَةً مَا بَقِيَ هَؤُلَاءِ.", "segs": null, "full_uz": "Bular qolgan ekan, fitna o'ti alangalanib qolaveradi.", "note": null},
{"num": 149, "time": "00:13:49,200 --> 00:14:01,200", "arabic": "أَرَى أَيُّهَا الْإِخْوَةُ أَنَّ مَا يَجْدُرُ بِنَا التَّفْكِيرُ بِهِ أَنْ نَجِدَ حَلًّا وَمَخْرَجًا لِمَا حَاقَ بِالْإِمَامِ أَحْمَدَ، وَكَيْفَ الْخَلَاصُ مِنْهَا؟", "segs": [{"ar": "أَرَى أَيُّهَا الْإِخْوَةُ أَنَّ مَا يَجْدُرُ", "uz": "Menimcha, birodarlar, biz o'ylashimiz kerak bo'lgan narsa"}, {"ar": "بِنَا التَّفْكِيرُ بِهِ أَنْ نَجِدَ حَلًّا", "uz": "— Imom Ahmadga yetgan balo uchun yechim"}, {"ar": "وَمَخْرَجًا لِمَا حَاقَ بِالْإِمَامِ أَحْمَدَ،", "uz": "va chiqish yo'lini topish,"}, {"ar": "وَكَيْفَ الْخَلَاصُ مِنْهَا؟", "uz": "va undan qanday qutulish mumkinligidir."}], "full_uz": "Menimcha, birodarlar, biz o'ylashimiz kerak bo'lgan narsa — Imom Ahmadga yetgan balo uchun yechim va chiqish yo'lini topish, va undan qanday qutulish mumkinligidir.", "note": null},
{"num": 151, "time": "00:14:03,379 --> 00:14:13,200", "arabic": "لَيْسَ لِأَبِي عَبْدِ اللَّهِ إِلَّا الْخُرُوجُ مِنْ بَغْدَادَ، وَإِنْ عَصَى أَوَامِرَ أَمِيرِ الْمُؤْمِنِينَ أَعْطَاهُ ذَرِيعَةً كَيْ يَنَالَ مِنْهُ.", "segs": [{"ar": "لَيْسَ لِأَبِي عَبْدِ اللَّهِ إِلَّا الْخُرُوجُ مِنْ بَغْدَادَ،", "uz": "Abu Abdullohga Bag'doddan chiqishdan boshqa chora yo'q,"}, {"ar": "وَإِنْ عَصَى أَوَامِرَ أَمِيرِ الْمُؤْمِنِينَ", "uz": "agar mo'minlar amirining buyrug'iga bo'ysunmasa,"}, {"ar": "أَعْطَاهُ ذَرِيعَةً كَيْ يَنَالَ مِنْهُ.", "uz": "bu unga qarshi choralar ko'rish uchun bahona bo'ladi."}], "full_uz": "Abu Abdullohga Bag'doddan chiqishdan boshqa chora yo'q, agar mo'minlar amirining buyrug'iga bo'ysunmasa, bu unga qarshi choralar ko'rish uchun bahona bo'ladi.", "note": null},
{"num": 153, "time": "00:14:13,200 --> 00:14:28,540", "arabic": "إِنَّ رَأْسَ الْأَفْعَى تَنْفُثُ سُمُومَهَا فِي كُلِّ مَكَانٍ وَفِي كُلِّ وَقْتٍ، وَلَنْ تَكُفَّ، لَنْ تَكُفَّ مَا دَامَتْ ثَمَّةَ نِحْلَةٌ هِيَ مَنْ يُغَذِّي الْوَاثِقَ وَيَمُدُّهُ فِي ضَلَالِهِ.", "segs": [{"ar": "إِنَّ رَأْسَ الْأَفْعَى تَنْفُثُ سُمُومَهَا فِي كُلِّ مَكَانٍ وَفِي كُلِّ وَقْتٍ،", "uz": "Ilonning boshi zaharini har yerda va har vaqtda sochadi,"}, {"ar": "وَلَنْ تَكُفَّ، لَنْ تَكُفَّ مَا دَامَتْ ثَمَّةَ نِحْلَةٌ", "uz": "va bir mazhab bor ekan, to'xtamaydi, to'xtamaydi,"}, {"ar": "هِيَ مَنْ يُغَذِّي الْوَاثِقَ وَيَمُدُّهُ فِي ضَلَالِهِ.", "uz": "Vosiqni oziqlantirib, uni adashuvida qo'llab-quvvatlayotgan mazhab."}], "full_uz": "Ilonning boshi zaharini har yerda va har vaqtda sochadi, va Vosiqni oziqlantirib, uni adashuvida qo'llab-quvvatlayotgan bir mazhab bor ekan, to'xtamaydi.", "note": null},
{"num": 159, "time": "00:14:28,540 --> 00:14:33,120", "arabic": "يَخْرُجُ الْإِمَامُ أَحْمَدُ مِنْ بَغْدَادَ؟ إِذَنْ فَبَغْدَادُ كُلُّهَا سَتَتْبَعُ.", "segs": null, "full_uz": "Imom Ahmad Bag'doddan chiqadimi? Unda butun Bag'dod uning ortidan boradi.", "note": null},
{"num": 161, "time": "00:14:33,120 --> 00:14:39,879", "arabic": "قَدْ خَرَجَ مَنْ هُوَ خَيْرٌ مِنْ أَحْمَدَ مِنْ بَلَدِهِ مُكْرَهًا، وَلَمْ يَزِدْهُ ذَلِكَ إِلَّا عُلُوًّا.", "segs": [{"ar": "قَدْ خَرَجَ مَنْ هُوَ خَيْرٌ", "uz": "Ahmaddan yaxshiroq bo'lgan kishi ham"}, {"ar": "مِنْ أَحْمَدَ مِنْ بَلَدِهِ مُكْرَهًا،", "uz": "o'z yurtidan majburan chiqib ketgan,"}, {"ar": "وَلَمْ يَزِدْهُ ذَلِكَ إِلَّا عُلُوًّا.", "uz": "va bu unga faqat yuksalish qo'shgan."}], "full_uz": "Ahmaddan yaxshiroq bo'lgan kishi ham o'z yurtidan majburan chiqib ketgan, va bu unga faqat yuksalish qo'shgan.", "note": null},
{"num": 163, "time": "00:14:39,879 --> 00:14:44,260", "arabic": "أَنَسِينَا سِيرَةَ نَبِيِّنَا أَيُّهَا الْإِخْوَةُ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟", "segs": null, "full_uz": "Payg'ambarimizning (sollallohu alayhi va sallam) siyratini unutdikmi, birodarlar?", "note": "Payg'ambar (sav)ning Makkadan Madinaga hijrat qilishiga ishora."},
{"num": 165, "time": "00:14:44,260 --> 00:14:50,820", "arabic": "أَنَا أَرَى غَيْرَ ذَلِكَ يَا إِمَامُ، أَرَى أَلَّا تَخْرُجَ.", "segs": null, "full_uz": "Men boshqacha fikrdaman, Imom, chiqmasligingizni to'g'ri deb bilaman.", "note": null},
{"num": 167, "time": "00:14:58,820 --> 00:15:13,820", "arabic": "تَأْبَى الْأَيَّامُ إِلَّا فِرَاقًا، ضَيَّعْتُكَ مَرَّةً لِنَلْتَقِيَ، وَهَا أَنَا أُضَيِّعُكَ مَرَّةً أُخْرَى.", "segs": [{"ar": "تَأْبَى الْأَيَّامُ إِلَّا فِرَاقًا، ضَيَّعْتُكَ مَرَّةً لِنَلْتَقِيَ،", "uz": "Kunlar faqat ayriliqdan boshqa narsani istamaydi. Seni bir marta yo'qotdim, uchrashish uchun,"}, {"ar": "وَهَا أَنَا أُضَيِّعُكَ مَرَّةً أُخْرَى.", "uz": "va mana men seni yana bir marta yo'qotyapman."}], "full_uz": "Kunlar faqat ayriliqdan boshqa narsani istamaydi. Seni bir marta yo'qotdim, uchrashish uchun, va mana men seni yana bir marta yo'qotyapman.", "note": null},
{"num": 170, "time": "00:15:13,820 --> 00:15:24,860", "arabic": "عِشْتُ غَرِيبَةً، وَأَنَا أَمُوتُ غَرِيبَةً أَيْضًا.", "segs": null, "full_uz": "G'arib bo'lib yashadim, g'arib bo'lib o'lyapman ham.", "note": null},
{"num": 172, "time": "00:15:24,860 --> 00:15:28,260", "arabic": "كُفِّي يَا أُخْتِي.", "segs": null, "full_uz": "Bas qiling, opajon.", "note": null},
{"num": 173, "time": "00:15:28,260 --> 00:15:54,139", "arabic": "بِأَبِي وَأُمِّي أَنْتِ يَا ابْنَةَ أَبِي، مُنْذُ أَنْ ضَيَّعَتْنَا الْأَيَّامُ مِنْ أُمِّنَا، وَأَنْتِ كُنْتِ لِي الْأَبَ وَالْأُمَّ يَا خَالَتَاهُ، أَدَامَ اللَّهُ أَنْ يَجْمَعَنَا فِي مُسْتَقَرِّ رَحْمَتِهِ.", "segs": [{"ar": "بِأَبِي وَأُمِّي أَنْتِ يَا ابْنَةَ أَبِي،", "uz": "Otam-onam senga fido bo'lsin, ey otamning qizi,"}, {"ar": "مُنْذُ أَنْ ضَيَّعَتْنَا الْأَيَّامُ مِنْ أُمِّنَا،", "uz": "kunlar bizni onamizdan judo qilganidan beri,"}, {"ar": "وَأَنْتِ كُنْتِ لِي الْأَبَ وَالْأُمَّ يَا خَالَتَاهُ،", "uz": "sen menga ota va ona bo'lding, ey xolajonim,"}, {"ar": "أَدَامَ اللَّهُ أَنْ يَجْمَعَنَا فِي مُسْتَقَرِّ رَحْمَتِهِ.", "uz": "Alloh bizni O'z rahmati qarorgohida jamlashda davom etsin."}], "full_uz": "Otam-onam senga fido bo'lsin, ey otamning qizi. Kunlar bizni onamizdan judo qilganidan beri, sen menga ota va ona bo'lding, ey xolajonim. Alloh bizni O'z rahmati qarorgohida jamlashda davom etsin.", "note": null},
{"num": 177, "time": "00:15:54,139 --> 00:15:57,200", "arabic": "الْكَلَامُ يَزِيدُ مِنْ تَعَبِكِ يَا خَالَةُ.", "segs": null, "full_uz": "Gapirish sizni charchatadi, xolajon.", "note": null},
{"num": 178, "time": "00:15:57,200 --> 00:16:00,460", "arabic": "لَنْ يُتْعِبَنِي الْكَلَامُ بَعْدَ الْيَوْمِ.", "segs": null, "full_uz": "Bugundan keyin gapirish meni charchatmaydi.", "note": null},
{"num": 179, "time": "00:16:00,460 --> 00:16:05,360", "arabic": "تَبَيَّنُوا، فَهَذَا آخِرُ كَلَامِي لَكُمْ.", "segs": null, "full_uz": "Tushunib qo'ying, bu sizlarga aytadigan oxirgi gapim.", "note": null},
{"num": 181, "time": "00:16:11,879 --> 00:16:17,720", "arabic": "دَعِي جَسَدًا مُضْنَاهُ الْأَلَمُ يَا أُخْتِي.", "segs": null, "full_uz": "Og'riq bezovta qilgan tanani tinch qo'y, opajon.", "note": null},
{"num": 182, "time": "00:16:17,720 --> 00:16:30,600", "arabic": "الْوَصِيَّةَ، لَا تَنْسَيْ، لَكِ وَلِبِنْتِكِ.", "segs": null, "full_uz": "Vasiyat, unutma, senga va qizingga tegishli.", "note": null},
{"num": 185, "time": "00:16:30,600 --> 00:16:41,100", "arabic": "لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ.", "segs": null, "full_uz": "Kuch-quvvat faqat Allohdandir.", "note": null},
{"num": 186, "time": "00:16:41,879 --> 00:16:45,840", "arabic": "أَحْسَبُ أَنَّ فِي ذَلِكَ خَطَرًا يَا ابْنَ هَانِئٍ، فَكَمَا تَعْلَمُونَ عُيُونُ أَمِيرِ الْمُؤْمِنِينَ فِي كُلِّ مَكَانٍ.", "segs": [{"ar": "أَحْسَبُ أَنَّ فِي ذَلِكَ", "uz": "Menimcha, bunda xavf bor,"}, {"ar": "خَطَرًا يَا ابْنَ هَانِئٍ،", "uz": "ey Ibn Hani,"}, {"ar": "فَكَمَا تَعْلَمُونَ عُيُونُ أَمِيرِ الْمُؤْمِنِينَ فِي كُلِّ مَكَانٍ.", "uz": "bilasizki, mo'minlar amirining ko'zlari har yerda."}], "full_uz": "Menimcha, bunda xavf bor, ey Ibn Hani, bilasizki, mo'minlar amirining ko'zlari har yerda.", "note": null},
{"num": 187, "time": "00:16:45,840 --> 00:16:51,039", "arabic": "يَا ابْنَ حَنْبَلٍ.", "segs": null, "full_uz": "Ey Ibn Hanbal.", "note": null},
{"num": 188, "time": "00:16:51,039 --> 00:16:52,120", "arabic": "يَا ابْنَ حَنْبَلٍ.", "segs": null, "full_uz": "Ey Ibn Hanbal.", "note": null},
{"num": 189, "time": "00:16:52,120 --> 00:16:57,139", "arabic": "لَوْ كَانَ أَمِيرُ الْمُؤْمِنِينَ يُرِيدُ الْإِمَامَ لَأَمَرَ بِالْقَبْضِ عَلَيْهِ.", "segs": null, "full_uz": "Agar mo'minlar amiri Imomni istaganida, uni qo'lga olishga buyruq bergan bo'lardi.", "note": null},
{"num": 191, "time": "00:16:57,139 --> 00:17:04,140", "arabic": "أَمْ أَنَّ الْوَاثِقَ نَسِيَ احْتِشَادَ أَهْلِ بَغْدَادَ أَمَامَ قَصْرِ أَبِيهِ فِي حَضْرَتِهِ حِينَ فَعَلَ مَا فَعَلَهُ بِالْإِمَامِ؟", "segs": [{"ar": "أَمْ أَنَّ الْوَاثِقَ نَسِيَ احْتِشَادَ أَهْلِ", "uz": "Yoki Vosiq Imomga qilingan ishni qilganida,"}, {"ar": "بَغْدَادَ أَمَامَ قَصْرِ أَبِيهِ فِي حَضْرَتِهِ حِينَ", "uz": "otasining saroyi oldida Bag'dod ahlining"}, {"ar": "فَعَلَ مَا فَعَلَهُ بِالْإِمَامِ؟", "uz": "o'z huzurida to'planganini unutdimi?"}], "full_uz": "Yoki Vosiq Imomga qilingan ishni qilganida, otasining saroyi oldida Bag'dod ahlining o'z huzurida to'planganini unutdimi?", "note": null},
{"num": 194, "time": "00:17:04,140 --> 00:17:09,160", "arabic": "لَكِنَّ الْوَاثِقَ لَيْسَ كَالْمُعْتَصِمِ.", "segs": null, "full_uz": "Lekin Vosiq Mu'tasimga o'xshamaydi.", "note": null},
{"num": 196, "time": "00:17:12,820 --> 00:17:24,940", "arabic": "وَلَكِنَّ النَّاسَ الَّذِينَ أَحَبُّوا الْإِمَامَ أَحْمَدَ وَاتَّبَعُوهُ وَخَاطَرُوا مِنْ أَجْلِهِ بِحَيَاتِهِمْ، مَا زَالُوا كَمَا هُمْ وَيَزِيدُونَ، وَالْوَاثِقُ يَعْرِفُ ذَلِكَ.", "segs": [{"ar": "وَلَكِنَّ النَّاسَ الَّذِينَ أَحَبُّوا الْإِمَامَ أَحْمَدَ وَاتَّبَعُوهُ وَخَاطَرُوا مِنْ أَجْلِهِ بِحَيَاتِهِمْ،", "uz": "Lekin Imom Ahmadni sevgan, unga ergashgan va uning uchun hayotlarini xavf ostiga qo'ygan odamlar hali ham o'sha-o'shalar,"}, {"ar": "مَا زَالُوا كَمَا هُمْ وَيَزِيدُونَ،", "uz": "hatto ko'payib boryapti,"}, {"ar": "وَالْوَاثِقُ يَعْرِفُ ذَلِكَ.", "uz": "va Vosiq buni biladi."}], "full_uz": "Lekin Imom Ahmadni sevgan, unga ergashgan va uning uchun hayotlarini xavf ostiga qo'ygan odamlar hali ham o'sha-o'shalar, hatto ko'payib boryapti, va Vosiq buni biladi.", "note": null},
{"num": 200, "time": "00:17:24,940 --> 00:17:35,040", "arabic": "وَلَوْلَا أَنَّهُ يَخْشَى أَنْ يُثِيرَ عَلَيْهِ النَّاسَ لَأَمَرَ بِالْقَبْضِ عَلَى الْإِمَامِ، وَلَمْ يَطْلُبْ إِلَيْهِ أَنْ لَا يُسَاكِنَهُ فِي أَرْضٍ هُوَ فِيهَا.", "segs": [{"ar": "وَلَوْلَا أَنَّهُ يَخْشَى أَنْ يُثِيرَ عَلَيْهِ", "uz": "Agar u odamlarni o'ziga qarshi qo'zg'atishdan qo'rqmasa edi,"}, {"ar": "النَّاسَ لَأَمَرَ بِالْقَبْضِ عَلَى الْإِمَامِ،", "uz": "Imomni qo'lga olishga buyruq berardi,"}, {"ar": "وَلَمْ يَطْلُبْ إِلَيْهِ أَنْ لَا", "uz": "va undan o'zi"}, {"ar": "يُسَاكِنَهُ فِي أَرْضٍ هُوَ فِيهَا.", "uz": "bo'lgan yerda birga yashamaslikni talab qilmasdi."}], "full_uz": "Agar u odamlarni o'ziga qarshi qo'zg'atishdan qo'rqmasa edi, Imomni qo'lga olishga buyruq berardi, va undan o'zi bo'lgan yerda birga yashamaslikni talab qilmasdi.", "note": null},
{"num": 203, "time": "00:17:35,040 --> 00:17:44,920", "arabic": "وَإِذَنْ؟ إِذَنْ إِنْ غَابَ الْإِمَامُ أَحْمَدُ عَنْ نَظَرِ الْوَاثِقِ فِي بَغْدَادَ، أَظُنُّ وَقْتَهَا أَنَّ أَمِيرَ الْمُؤْمِنِينَ سَيَكْتَفِي بِذَلِكَ وَلَنْ يَبْحَثَ عَنْ...", "segs": [{"ar": "وَإِذَنْ؟ إِذَنْ إِنْ غَابَ الْإِمَامُ أَحْمَدُ", "uz": "Xo'sh? Unda,"}, {"ar": "عَنْ نَظَرِ الْوَاثِقِ فِي بَغْدَادَ،", "uz": "agar Imom Ahmad Bag'dodda Vosiqning ko'zidan g'oyib bo'lsa,"}, {"ar": "أَظُنُّ وَقْتَهَا أَنَّ أَمِيرَ الْمُؤْمِنِينَ سَيَكْتَفِي بِذَلِكَ", "uz": "o'shanda mo'minlar amiri shu bilan kifoyalanib,"}, {"ar": "وَلَنْ يَبْحَثَ عَنْ...", "uz": "qidirmasligini o'ylayman..."}], "full_uz": "Xo'sh? Unda, agar Imom Ahmad Bag'dodda Vosiqning ko'zidan g'oyib bo'lsa, o'shanda mo'minlar amiri shu bilan kifoyalanib, qidirmasligini o'ylayman...", "note": null},
{"num": 207, "time": "00:17:44,920 --> 00:17:54,200", "arabic": "الْمُعْتَزِلَةُ سَاهِرُونَ عَلَى الْمَالِ، عُيُونُهُمْ سَاهِرَةٌ لِلسُّلْطَانِ، وَلَهُمْ عُيُونٌ فِي كُلِّ مَكَانٍ.", "segs": [{"ar": "الْمُعْتَزِلَةُ سَاهِرُونَ عَلَى الْمَالِ،", "uz": "Mu'tazila mol-davlat uchun uyg'oq,"}, {"ar": "عُيُونُهُمْ سَاهِرَةٌ لِلسُّلْطَانِ، وَلَهُمْ عُيُونٌ فِي كُلِّ مَكَانٍ.", "uz": "ularning ko'zlari sulton uchun uyg'oq, va ularning har yerda ko'zlari bor."}], "full_uz": "Mu'tazila mol-davlat uchun uyg'oq, ularning ko'zlari sulton uchun uyg'oq, va ularning har yerda ko'zlari bor.", "note": null},
{"num": 210, "time": "00:17:54,200 --> 00:17:58,980", "arabic": "لَا أَدْرِي، قَلْبِي لَيْسَ مُطْمَئِنًّا.", "segs": null, "full_uz": "Bilmayman, qalbim xotirjam emas.", "note": null},
{"num": 212, "time": "00:17:58,980 --> 00:18:02,680", "arabic": "مَا رَأْيُكَ يَا أَبَا عَبْدِ اللَّهِ؟", "segs": null, "full_uz": "Fikringiz qanday, ey Abu Abdulloh?", "note": null},
{"num": 213, "time": "00:18:05,680 --> 00:18:20,759", "arabic": "قَطْعُ رَأْسِ الْحَيَّةِ أَوْلَى مِنْ ذَنَبِهَا يَا مَوْلَايَ.", "segs": null, "full_uz": "Ilonning boshini kesish dumini kesishdan afzalroq, xo'jayinim.", "note": null},
{"num": 214, "time": "00:18:20,759 --> 00:18:31,100", "arabic": "أَجَلْ يَا مَوْلَايَ إِنَّهُ مِنْ أَهْلِ الضَّلَالَةِ، وَمَا يَلْبَثُ أَنْ يَبُثَّ بِدَعَهُ بَيْنَ النَّاسِ.", "segs": [{"ar": "أَجَلْ يَا مَوْلَايَ إِنَّهُ مِنْ أَهْلِ الضَّلَالَةِ،", "uz": "Ha, xo'jayinim, u adashuv ahlidandir,"}, {"ar": "وَمَا يَلْبَثُ أَنْ يَبُثَّ بِدَعَهُ بَيْنَ النَّاسِ.", "uz": "va o'z bid'atlarini odamlar orasiga tarqatishga vaqt kutmaydi."}], "full_uz": "Ha, xo'jayinim, u adashuv ahlidandir, va o'z bid'atlarini odamlar orasiga tarqatishga vaqt kutmaydi.", "note": null},
{"num": 216, "time": "00:18:31,100 --> 00:18:35,000", "arabic": "وَإِنَّمَا الرَّأْيُ رَأْيُ أَمِيرِ الْمُؤْمِنِينَ.", "segs": null, "full_uz": "Fikr esa faqat mo'minlar amirining fikridir.", "note": null},
{"num": 217, "time": "00:18:35,000 --> 00:18:45,720", "arabic": "إِنَّ لِابْنِ حَنْبَلٍ مَقَامًا عَالِيًا وَشِيَعًا كُثُرًا، وَقَدْ عَلِمْتُمْ مَا فَعَلُوهُ مِنْ قَبْلُ.", "segs": [{"ar": "إِنَّ لِابْنِ حَنْبَلٍ مَقَامًا عَالِيًا وَشِيَعًا كُثُرًا،", "uz": "Ibn Hanbalning yuqori martabasi va ko'plab tarafdorlari bor,"}, {"ar": "وَقَدْ عَلِمْتُمْ مَا فَعَلُوهُ مِنْ قَبْلُ.", "uz": "va siz ilgari ularning nima qilganini bilasiz."}], "full_uz": "Ibn Hanbalning yuqori martabasi va ko'plab tarafdorlari bor, va siz ilgari ularning nima qilganini bilasiz.", "note": null},
{"num": 219, "time": "00:18:45,720 --> 00:18:57,579", "arabic": "إِنَّ الْحُكْمَ لَا يَطِيبُ فِي ظِلَالِ الْقَلَاقِلِ.", "segs": null, "full_uz": "Hukmronlik notinchlik soyasida yaxshi kechmaydi.", "note": null},
{"num": 220, "time": "00:19:05,000 --> 00:19:11,380", "arabic": "إِنَّهُمْ عَوَامٌّ لَا يُؤْبَهُ لَهُمْ يَا مَوْلَايَ.", "segs": null, "full_uz": "Ular e'tiborga olinmaydigan omma xalqdir, xo'jayinim.", "note": null},
{"num": 221, "time": "00:19:11,380 --> 00:19:20,700", "arabic": "هَذَا مَا يُخْشَى مِنْهُ أَيُّهَا الْقَاضِي، فَالْعَوَامُّ الَّذِينَ يَتْبَعُونَهُ يَسِيرُونَ خَلْفَهُ عَلَى غَيْرِ هُدًى.", "segs": [{"ar": "هَذَا مَا يُخْشَى مِنْهُ أَيُّهَا الْقَاضِي،", "uz": "Aynan shundan qo'rqiladi, ey qozi,"}, {"ar": "فَالْعَوَامُّ الَّذِينَ يَتْبَعُونَهُ يَسِيرُونَ خَلْفَهُ عَلَى غَيْرِ هُدًى.", "uz": "chunki unga ergashgan omma yo'l-yo'riqsiz uning ortidan yuradi."}], "full_uz": "Aynan shundan qo'rqiladi, ey qozi, chunki unga ergashgan omma yo'l-yo'riqsiz uning ortidan yuradi.", "note": null},
{"num": 223, "time": "00:19:20,700 --> 00:19:27,619", "arabic": "وَلَوْلَا أَنَّنَا نَتَوَرَّعُ أَنْ نَخُوضَ فِي دِمَائِهِمْ لَحَمَلْنَاهُمْ عَلَى الْحَقِّ حَمْلًا.", "segs": [{"ar": "وَلَوْلَا أَنَّنَا نَتَوَرَّعُ أَنْ نَخُوضَ فِي", "uz": "Agar biz ularning qonlariga qo'l urishdan tiyilmaganimizda,"}, {"ar": "دِمَائِهِمْ لَحَمَلْنَاهُمْ عَلَى الْحَقِّ حَمْلًا.", "uz": "ularni haqqa majburan olib borgan bo'lardik."}], "full_uz": "Agar biz ularning qonlariga qo'l urishdan tiyilmaganimizda, ularni haqqa majburan olib borgan bo'lardik.", "note": null},
{"num": 225, "time": "00:19:27,619 --> 00:19:35,319", "arabic": "مَا أَرَاهُ أَنَّ سَيْفَ الْحِلْمِ أَمْضَى مِنْ سَيْفِ الْبَطْشِ.", "segs": null, "full_uz": "Menimcha, muloyimlik qilichi shafqatsizlik qilichidan o'tkirroqdir.", "note": null},
{"num": 226, "time": "00:19:35,319 --> 00:19:41,939", "arabic": "أَلَا يَكْفِينَا أَنَّنَا لَا نَرَاهُ وَلَا نَسْمَعُهُ؟", "segs": null, "full_uz": "Uni ko'rmasligimiz va eshitmasligimiz bizga yetarli emasmi?", "note": null},
{"num": 227, "time": "00:19:41,939 --> 00:19:52,059", "arabic": "يَا قَوْمُ، لَقَدْ غَيَّبْنَا صَوْتَهُ عَنْ مَسَامِعِ أَهْلِ بَغْدَادَ، وَسُرْعَانَ مَا سَيَغِيبُ عَنْ قُلُوبِهِمْ.", "segs": [{"ar": "يَا قَوْمُ، لَقَدْ غَيَّبْنَا صَوْتَهُ عَنْ مَسَامِعِ أَهْلِ بَغْدَادَ،", "uz": "Ey qavm, biz uning ovozini Bag'dod ahlining qulog'idan g'oyib qildik,"}, {"ar": "وَسُرْعَانَ مَا سَيَغِيبُ عَنْ قُلُوبِهِمْ.", "uz": "va tez orada ularning qalbidan ham g'oyib bo'ladi."}], "full_uz": "Ey qavm, biz uning ovozini Bag'dod ahlining qulog'idan g'oyib qildik, va tez orada ularning qalbidan ham g'oyib bo'ladi.", "note": null},
{"num": 229, "time": "00:19:52,059 --> 00:20:06,380", "arabic": "لِيَأْتِ الدَّوْرُ عَلَيْكُمْ أَنْتُمْ لِإِقْنَاعِهِمْ بِالْحَقِّ، وَعِنْدَ ذَلِكَ نَقُولُ قَدْ هَدَيْنَاهُمْ إِلَى الْحَقِّ دُونَ نُقْطَةِ دَمٍ بَرِيئَةٍ.", "segs": [{"ar": "لِيَأْتِ الدَّوْرُ عَلَيْكُمْ أَنْتُمْ لِإِقْنَاعِهِمْ بِالْحَقِّ،", "uz": "Endi navbat sizlarga kelsin, ularni haqqa ishontirish uchun,"}, {"ar": "وَعِنْدَ ذَلِكَ نَقُولُ قَدْ هَدَيْنَاهُمْ إِلَى", "uz": "va o'shanda biz ularni bir tomchi"}, {"ar": "الْحَقِّ دُونَ نُقْطَةِ دَمٍ بَرِيئَةٍ.", "uz": "begunoh qon to'kmasdan haqqa hidoyat qildik, deymiz."}], "full_uz": "Endi navbat sizlarga kelsin, ularni haqqa ishontirish uchun, va o'shanda biz ularni bir tomchi begunoh qon to'kmasdan haqqa hidoyat qildik, deymiz.", "note": null},
{"num": 233, "time": "00:20:06,380 --> 00:20:12,740", "arabic": "نِعْمَ الرَّأْيُ يَا مَوْلَايَ، نِعْمَ الرَّأْيُ.", "segs": null, "full_uz": "Qanday ham yaxshi fikr, xo'jayinim, qanday ham yaxshi fikr.", "note": null},
{"num": 235, "time": "00:20:12,740 --> 00:20:27,400", "arabic": "لَا حَوْلَ وَلَا قُوَّةَ.", "segs": null, "full_uz": "Kuch-quvvat faqat Allohdandir.", "note": null},
{"num": 236, "time": "00:20:27,400 --> 00:20:37,000", "arabic": "الْمُؤْمِنُ مُبْتَلًى يَا أُمَّ عَبْدِ اللَّهِ، وَلَيْسَ لِقَضَاءِ اللَّهِ وَقَدَرِهِ إِلَّا الرِّضَا وَالتَّسْلِيمُ.", "segs": [{"ar": "الْمُؤْمِنُ مُبْتَلًى يَا أُمَّ عَبْدِ اللَّهِ،", "uz": "Mo'min sinaladi, ey Abdullohning onasi,"}, {"ar": "وَلَيْسَ لِقَضَاءِ اللَّهِ وَقَدَرِهِ إِلَّا الرِّضَا وَالتَّسْلِيمُ.", "uz": "va Allohning qazo va qadariga faqat rozilik va taslim bo'lish mumkin."}], "full_uz": "Mo'min sinaladi, ey Abdullohning onasi, va Allohning qazo va qadariga faqat rozilik va taslim bo'lish mumkin.", "note": null},
{"num": 239, "time": "00:20:37,000 --> 00:20:44,420", "arabic": "لَا إِلَهَ إِلَّا اللَّهُ، هُوَ حَسْبُنَا وَلَنْ يُضَيِّعَنَا إِنْ شَاءَ اللَّهُ.", "segs": [{"ar": "لَا إِلَهَ إِلَّا اللَّهُ،", "uz": "Allohdan boshqa iloh yo'q,"}, {"ar": "هُوَ حَسْبُنَا وَلَنْ يُضَيِّعَنَا إِنْ شَاءَ اللَّهُ.", "uz": "U bizga kifoya qiladi va bizni zoye qilmaydi, inshaalloh."}], "full_uz": "Allohdan boshqa iloh yo'q, U bizga kifoya qiladi va bizni zoye qilmaydi, inshaalloh.", "note": null},
{"num": 242, "time": "00:20:44,420 --> 00:21:04,420", "arabic": "سُنَّةُ اللَّهِ فِي الْأَرْضِ مَاضِيَةٌ، قَالَ تَعَالَى: أَحَسِبَ النَّاسُ أَنْ يُتْرَكُوا أَنْ يَقُولُوا آمَنَّا وَهُمْ لَا يُفْتَنُونَ؟ وَلَقَدْ فَتَنَّا الَّذِينَ مِنْ قَبْلِهِمْ فَلَيَعْلَمَنَّ اللَّهُ الَّذِينَ صَدَقُوا وَلَيَعْلَمَنَّ الْكَاذِبِينَ.", "segs": [{"ar": "سُنَّةُ اللَّهِ فِي الْأَرْضِ مَاضِيَةٌ،", "uz": "Allohning yerdagi qonuni o'z yo'lida davom"}, {"ar": "قَالَ تَعَالَى: أَحَسِبَ النَّاسُ أَنْ يُتْرَكُوا أَنْ يَقُولُوا آمَنَّا", "uz": "etadi. U taolo aytadi: \"Odamlar, biz iymon keltirdik, deyishlari bilanoq,"}, {"ar": "وَهُمْ لَا يُفْتَنُونَ؟", "uz": "sinovsiz qoldirilishlarini o'ylaydilarmi? Albatta,"}, {"ar": "وَلَقَدْ فَتَنَّا الَّذِينَ مِنْ قَبْلِهِمْ", "uz": "Biz ulardan avvalgilarni ham sinaganmiz. Alloh haqiqatan"}, {"ar": "فَلَيَعْلَمَنَّ اللَّهُ الَّذِينَ صَدَقُوا وَلَيَعْلَمَنَّ الْكَاذِبِينَ.", "uz": "kim rost so'zlaganini va kim yolg'onchilarni albatta biladi.\""}], "full_uz": "Allohning yerdagi qonuni o'z yo'lida davom etadi. U taolo aytadi: \"Odamlar, biz iymon keltirdik, deyishlari bilanoq, sinovsiz qoldirilishlarini o'ylaydilarmi? Albatta, Biz ulardan avvalgilarni ham sinaganmiz. Alloh haqiqatan kim rost so'zlaganini va kim yolg'onchilarni albatta biladi.\"", "note": "Qur'on, Ankabut surasi, 2-3-oyatlar."},
{"num": 249, "time": "00:21:04,420 --> 00:21:08,160", "arabic": "الْحَمْدُ لِلَّهِ عَلَى كُلِّ حَالٍ.", "segs": null, "full_uz": "Har qanday holatda ham hamd Allohga xosdir.", "note": null},
{"num": 250, "time": "00:21:08,160 --> 00:21:16,800", "arabic": "إِنَّمَا أَبْكِي عَلَى فِرَاقِكِ الَّذِي لَمْ نَتَعَوَّدْ، لَا أَنَا وَلَا ابْنُكِ عَبْدُ اللَّهِ.", "segs": [{"ar": "إِنَّمَا أَبْكِي عَلَى فِرَاقِكِ الَّذِي لَمْ نَتَعَوَّدْ،", "uz": "Men faqat sizdan ayrilishga — men ham,"}, {"ar": "لَا أَنَا وَلَا ابْنُكِ عَبْدُ اللَّهِ.", "uz": "o'g'lingiz Abdulloh ham o'rganmagan bu ayriliqqa — yig'layapman."}], "full_uz": "Men faqat sizdan ayrilishga — men ham, o'g'lingiz Abdulloh ham o'rganmagan bu ayriliqqa — yig'layapman.", "note": null},
{"num": 252, "time": "00:21:16,800 --> 00:21:20,140", "arabic": "رَحْمَةُ اللَّهِ عَلَيْكِ يَا أُمِّي.", "segs": null, "full_uz": "Allohning rahmati sizga bo'lsin, onajon.", "note": null},
{"num": 253, "time": "00:21:20,140 --> 00:21:25,000", "arabic": "كُنْتُ أَغِيبُ عَنْهَا الشُّهُورَ وَالسِّنِينَ، وَمَا أَرَاهَا إِلَّا رَاضِيَةً مُحْتَسِبَةً.", "segs": [{"ar": "كُنْتُ أَغِيبُ عَنْهَا الشُّهُورَ وَالسِّنِينَ،", "uz": "Oylar va yillar davomida undan uzoqda bo'lar edim,"}, {"ar": "وَمَا أَرَاهَا إِلَّا رَاضِيَةً مُحْتَسِبَةً.", "uz": "lekin uni har doim faqat rozi va sabr bilan ko'rar edim."}], "full_uz": "Oylar va yillar davomida undan uzoqda bo'lar edim, lekin uni har doim faqat rozi va sabr bilan ko'rar edim.", "note": null},
{"num": 255, "time": "00:21:25,000 --> 00:21:32,259", "arabic": "ثُمَّ إِنَّ أَبِي يَا خَالَةُ لَنْ يَكُونَ بَعِيدًا عَنْ هُنَا إِنْ شَاءَ اللَّهُ، وَكُلَّمَا اشْتَقْتُمْ لِرُؤْيَتِهِ سَنَتَدَبَّرُ ذَلِكَ.", "segs": [{"ar": "ثُمَّ إِنَّ أَبِي يَا خَالَةُ لَنْ", "uz": "Bundan tashqari, dadam, inshaalloh,"}, {"ar": "يَكُونَ بَعِيدًا عَنْ هُنَا إِنْ شَاءَ اللَّهُ،", "uz": "bu yerdan uzoqda bo'lmaydi, xolajon, va uni ko'rishni sog'ingan"}, {"ar": "وَكُلَّمَا اشْتَقْتُمْ لِرُؤْيَتِهِ سَنَتَدَبَّرُ ذَلِكَ.", "uz": "sari buni hal qilamiz."}], "full_uz": "Bundan tashqari, dadam, inshaalloh, bu yerdan uzoqda bo'lmaydi, xolajon, va uni ko'rishni sog'ingan sari buni hal qilamiz.", "note": null},
{"num": 258, "time": "00:21:32,259 --> 00:21:40,340", "arabic": "غَفَرَ اللَّهُ لِمَنْ فَرَّقَ بَيْنَ الرَّجُلِ وَأَهْلِهِ وَزَرَعَ الشَّكَّ فِي نُفُوسِنَا.", "segs": [{"ar": "غَفَرَ اللَّهُ لِمَنْ فَرَّقَ بَيْنَ الرَّجُلِ", "uz": "Alloh erkak va uning oilasi orasini ajratib,"}, {"ar": "وَأَهْلِهِ وَزَرَعَ الشَّكَّ فِي نُفُوسِنَا.", "uz": "qalbimizga shubha ekkan kimsani mag'firat qilsin."}], "full_uz": "Alloh erkak va uning oilasi orasini ajratib, qalbimizga shubha ekkan kimsani mag'firat qilsin.", "note": null},
{"num": 260, "time": "00:21:40,340 --> 00:21:47,660", "arabic": "لَمْ أَعُدْ أَطْمَئِنُّ إِلَى شَيْءٍ يَا صَالِحُ، وَأَخْشَى...", "segs": null, "full_uz": "Endi hech narsaga xotirjam bo'lolmayapman, Solih, va qo'rqamanki...", "note": null},
{"num": 262, "time": "00:21:47,660 --> 00:21:55,140", "arabic": "لَا تَخْشَيْ شَيْئًا يَا رَيْحَانَةُ، إِنَّ مَنْ يُؤْوِينِي عِنْدَهُ مِنْ خِيرَةِ تَلَامِيذِي، لَا أُزَكِّيهِ عَلَى اللَّهِ.", "segs": [{"ar": "لَا تَخْشَيْ شَيْئًا يَا رَيْحَانَةُ،", "uz": "Hech narsadan qo'rqma, ey Rayhona,"}, {"ar": "إِنَّ مَنْ يُؤْوِينِي عِنْدَهُ مِنْ خِيرَةِ تَلَامِيذِي،", "uz": "meni boshpana bergan kishi eng yaxshi shogirdlarimdan biri,"}, {"ar": "لَا أُزَكِّيهِ عَلَى اللَّهِ.", "uz": "uni Alloh oldida oqlamayman, lekin ishonaman."}], "full_uz": "Hech narsadan qo'rqma, ey Rayhona, meni boshpana bergan kishi eng yaxshi shogirdlarimdan biri, uni Alloh oldida oqlamayman, lekin ishonaman.", "note": null},
{"num": 265, "time": "00:21:55,140 --> 00:22:05,300", "arabic": "حَمَاكَ اللَّهُ يَا أَبَا عَبْدِ اللَّهِ، وَحَفِظَكَ مِنْ كُلِّ مَكْرُوهٍ وَسُوءٍ، وَأَبْقَاكَ لَنَا عَوْنًا وَسَنَدًا.", "segs": [{"ar": "حَمَاكَ اللَّهُ يَا أَبَا عَبْدِ اللَّهِ،", "uz": "Alloh sizni himoya qilsin, ey Abu Abdulloh,"}, {"ar": "وَحَفِظَكَ مِنْ كُلِّ مَكْرُوهٍ وَسُوءٍ،", "uz": "va sizni har qanday yomonlik va zarardan asrasin,"}, {"ar": "وَأَبْقَاكَ لَنَا عَوْنًا وَسَنَدًا.", "uz": "va bizga yordamchi va tayanch qilib qoldirsin."}], "full_uz": "Alloh sizni himoya qilsin, ey Abu Abdulloh, va sizni har qanday yomonlik va zarardan asrasin, va bizga yordamchi va tayanch qilib qoldirsin.", "note": null},
{"num": 268, "time": "00:22:05,299 --> 00:22:13,319", "arabic": "أَسْتَوْدِعُكَ اللَّهَ يَا رَيْحَانَةُ، أَسْتَوْدِعُ اللَّهَ دِينَكِ وَأَمَانَتَكِ وَخَوَاتِيمَ عَمَلِكِ.", "segs": [{"ar": "أَسْتَوْدِعُكَ اللَّهَ يَا رَيْحَانَةُ،", "uz": "Seni Allohga topshiraman, ey Rayhona,"}, {"ar": "أَسْتَوْدِعُ اللَّهَ دِينَكِ وَأَمَانَتَكِ وَخَوَاتِيمَ عَمَلِكِ.", "uz": "dining, omonating va amalingning yakunini Allohga topshiraman."}], "full_uz": "Seni Allohga topshiraman, ey Rayhona, dining, omonating va amalingning yakunini Allohga topshiraman.", "note": null},
{"num": 270, "time": "00:22:13,319 --> 00:22:16,079", "arabic": "نَذْهَبُ يَا وَلَدِي.", "segs": null, "full_uz": "Ketamiz, o'g'lim.", "note": null},
{"num": 271, "time": "00:22:16,079 --> 00:22:17,639", "arabic": "تَفَضَّلْ يَا رَيْحَانَةُ.", "segs": null, "full_uz": "Marhamat, ey Rayhona.", "note": null},
{"num": 272, "time": "00:22:17,639 --> 00:22:19,299", "arabic": "لَا تَنْسَيْنَا مِنْ صَالِحِ دُعَائِكِ.", "segs": null, "full_uz": "Bizni solih duoingizdan mahrum qilmang.", "note": null},
{"num": 273, "time": "00:22:20,200 --> 00:22:40,299", "arabic": "تَفَضَّلْ يَا إِمَامُ، تَفَضَّلْ.", "segs": null, "full_uz": "Marhamat, Imom, marhamat.", "note": null},
{"num": 275, "time": "00:22:40,299 --> 00:22:42,000", "arabic": "يَا اللَّهُ.", "segs": null, "full_uz": "Yo Alloh.", "note": null},
{"num": 276, "time": "00:22:42,000 --> 00:22:50,740", "arabic": "عُذْرًا يَا إِمَامُ، فَالْبَيْتُ عَلَى قَدْرِ حَالِ صَاحِبِهِ، وَمَا أَظُنُّهُ يَلِيقُ بِمَقَامِكَ، وَلَكِنْ...", "segs": [{"ar": "عُذْرًا يَا إِمَامُ، فَالْبَيْتُ عَلَى قَدْرِ حَالِ صَاحِبِهِ،", "uz": "Uzr, Imom, uy egasining ahvoliga yarasha,"}, {"ar": "وَمَا أَظُنُّهُ يَلِيقُ بِمَقَامِكَ، وَلَكِنْ...", "uz": "sizning martabangizga loyiq deb o'ylamayman, lekin..."}], "full_uz": "Uzr, Imom, uy egasining ahvoliga yarasha, sizning martabangizga loyiq deb o'ylamayman, lekin...", "note": null},
{"num": 280, "time": "00:22:50,740 --> 00:22:52,019", "arabic": "لَا تُكْمِلْ يَا ابْنَ هَانِئٍ.", "segs": null, "full_uz": "Davom ettirmang, Ibn Hani.", "note": null},
{"num": 281, "time": "00:22:52,019 --> 00:22:58,480", "arabic": "الْبَيْتُ بِطِيبِ أَهْلِهِ وَكَرَمِهِمْ، بَارَكَ اللَّهُ فِيهِ وَفِي أَهْلِهِ.", "segs": null, "full_uz": "Uy o'z ahlining poklik va saxovati bilan qadrlidir, Alloh unga va uning ahliga barakot bersin.", "note": null},
{"num": 283, "time": "00:22:58,480 --> 00:23:04,879", "arabic": "كُلُّ مَا أَبْتَغِيهِ مَكَانٌ آمِنٌ يَكُونُ بَعِيدًا عَنْ عُيُونِ الْوَاثِقِ وَرِجَالِهِ.", "segs": [{"ar": "كُلُّ مَا أَبْتَغِيهِ مَكَانٌ آمِنٌ يَكُونُ بَعِيدًا عَنْ عُيُونِ الْوَاثِقِ", "uz": "Men istagan yagona narsa — Vosiq va uning odamlarining ko'zidan uzoq bo'lgan xavfsiz"}, {"ar": "وَرِجَالِهِ.", "uz": "joydir."}], "full_uz": "Men istagan yagona narsa — Vosiq va uning odamlarining ko'zidan uzoq bo'lgan xavfsiz joydir.", "note": null},
{"num": 285, "time": "00:23:04,880 --> 00:23:11,860", "arabic": "بِإِذْنِ اللَّهِ فِي دَارِي هَذِهِ لَنْ تَصِلَ إِلَيْكَ أَيْدِي الْوَاثِقِ أَوْ غَيْرِهِ.", "segs": [{"ar": "بِإِذْنِ اللَّهِ فِي دَارِي هَذِهِ لَنْ", "uz": "Alloh xohlasa, mening bu uyimda Vosiq"}, {"ar": "تَصِلَ إِلَيْكَ أَيْدِي الْوَاثِقِ أَوْ غَيْرِهِ.", "uz": "yoki boshqa birovning qo'li senga yetmaydi."}], "full_uz": "Alloh xohlasa, mening bu uyimda Vosiq yoki boshqa birovning qo'li senga yetmaydi.", "note": null},
{"num": 286, "time": "00:23:11,860 --> 00:23:15,640", "arabic": "بَارَكَ اللَّهُ فِيكَ وَجَزَاكَ عَنِّي كُلَّ خَيْرٍ.", "segs": null, "full_uz": "Alloh senga barakot bersin va mendan senga har qanday yaxshilikni bersin.", "note": null},
{"num": 287, "time": "00:23:15,640 --> 00:23:21,640", "arabic": "بَلْ جَزَى اللَّهُ الْوَاثِقَ خَيْرًا، فَقَدْ أَسْعَدَنِي بِتَشْرِيفِكَ دَارِي يَا أَبَا عَبْدِ اللَّهِ.", "segs": [{"ar": "بَلْ جَزَى اللَّهُ الْوَاثِقَ خَيْرًا،", "uz": "Aksincha, Alloh Vosiqqa yaxshilik bersin,"}, {"ar": "فَقَدْ أَسْعَدَنِي بِتَشْرِيفِكَ دَارِي يَا أَبَا عَبْدِ اللَّهِ.", "uz": "chunki u meni uyimni sharaflaganingiz bilan xursand qildi, ey Abu Abdulloh."}], "full_uz": "Aksincha, Alloh Vosiqqa yaxshilik bersin, chunki u meni uyimni sharaflaganingiz bilan xursand qildi, ey Abu Abdulloh.", "note": null},
{"num": 289, "time": "00:23:21,640 --> 00:23:39,280", "arabic": "لِلَّهِ مَا أَخَذَ وَلَهُ مَا أَعْطَى، وَكُلُّ شَيْءٍ عِنْدَهُ بِأَجَلٍ مُسَمًّى، حَسْبُنَا اللَّهُ وَنِعْمَ الْوَكِيلُ.", "segs": [{"ar": "لِلَّهِ مَا أَخَذَ وَلَهُ مَا أَعْطَى،", "uz": "Olgan narsa ham, bergan narsa ham Allohnikidir,"}, {"ar": "وَكُلُّ شَيْءٍ عِنْدَهُ بِأَجَلٍ مُسَمًّى،", "uz": "va Uning huzurida har bir narsaning belgilangan ajali bor. Alloh bizga kifoya qiladi,"}, {"ar": "حَسْبُنَا اللَّهُ وَنِعْمَ الْوَكِيلُ.", "uz": "U qanday ham yaxshi vakildir."}], "full_uz": "Olgan narsa ham, bergan narsa ham Allohnikidir, va Uning huzurida har bir narsaning belgilangan ajali bor. Alloh bizga kifoya qiladi, U qanday ham yaxshi vakildir.", "note": "\"لله ما أخذ وله ما أعطى\" — Payg'ambar (sav)ning ta'ziya so'zlaridan (Buxoriy, Muslim)."},
{"num": 292, "time": "00:23:39,279 --> 00:23:56,500", "arabic": "أَلَمْ يَكُنْ مِنَ الْأَصْلَحِ لَوْ أَنَّ زَوْجَ شَفِيعٍ أَوْصَتْ بِالْقَصْرِ وَالدَّكَاكِينِ لِأَهْلِ زَوْجِهَا؟", "segs": [{"ar": "أَلَمْ يَكُنْ مِنَ الْأَصْلَحِ لَوْ أَنَّ زَوْجَ شَفِيعٍ أَوْصَتْ بِالْقَصْرِ", "uz": "Shafi'ning xotini saroy va do'konlarni eri oilasiga vasiyat qilganida yaxshiroq"}, {"ar": "وَالدَّكَاكِينِ لِأَهْلِ زَوْجِهَا؟", "uz": "bo'lmasmidi?"}], "full_uz": "Shafi'ning xotini saroy va do'konlarni eri oilasiga vasiyat qilganida yaxshiroq bo'lmasmidi?", "note": null},
{"num": 294, "time": "00:23:56,500 --> 00:24:03,139", "arabic": "إِنَّهُ مَالُهَا، وَالْحُرُّ يُوصِي بِمَا شَاءَ لِمَنْ شَاءَ.", "segs": null, "full_uz": "Bu uning mol-mulki, ozod kishi esa xohlagan narsasini xohlagan kishiga vasiyat qiladi.", "note": null},
{"num": 296, "time": "00:24:03,139 --> 00:24:12,680", "arabic": "ثُمَّ إِنَّهَا أَوْصَتْ بِالْمَالِ لِأُخْتِهَا وَابْنَةِ أُخْتِهَا، سَيَذْهَبُ كُلُّ هَذَا لِمَرْوَانَةَ وَعُمَرَ الْإِسْكَافِيِّ.", "segs": [{"ar": "ثُمَّ إِنَّهَا أَوْصَتْ بِالْمَالِ لِأُخْتِهَا وَابْنَةِ أُخْتِهَا،", "uz": "Bundan tashqari, u molini singlisiga va singlisining qiziga vasiyat qildi,"}, {"ar": "سَيَذْهَبُ كُلُّ هَذَا لِمَرْوَانَةَ وَعُمَرَ الْإِسْكَافِيِّ.", "uz": "bularning barchasi Marvanaga va Umar al-Iskofiyga o'tadi."}], "full_uz": "Bundan tashqari, u molini singlisiga va singlisining qiziga vasiyat qildi, bularning barchasi Marvanaga va Umar al-Iskofiyga o'tadi.", "note": null},
{"num": 298, "time": "00:24:12,680 --> 00:24:38,800", "arabic": "الدُّنْيَا كَمَا تَرَاهَا دُوَلُ حُظُوظٍ يَا أَبَا عَبْدِ الرَّحْمَنِ، فَصَانِعُ الشُّمُوعِ صَارَ صَاحِبَ قَصْرٍ، وَالْإِسْكَافِيُّ صَارَ مِنْ كِبَارِ التُّجَّارِ.", "segs": [{"ar": "الدُّنْيَا كَمَا تَرَاهَا دُوَلُ حُظُوظٍ يَا أَبَا عَبْدِ الرَّحْمَنِ،", "uz": "Dunyo, ko'rib turganingizdek, baxt-omadning aylanishidir, ey Abu Abdurahmon,"}, {"ar": "فَصَانِعُ الشُّمُوعِ صَارَ صَاحِبَ قَصْرٍ،", "uz": "sham yasovchi saroy egasiga aylandi,"}, {"ar": "وَالْإِسْكَافِيُّ صَارَ مِنْ كِبَارِ التُّجَّارِ.", "uz": "etikdo'z esa katta savdogarlardan biriga aylandi."}], "full_uz": "Dunyo, ko'rib turganingizdek, baxt-omadning aylanishidir, ey Abu Abdurahmon, sham yasovchi saroy egasiga aylandi, etikdo'z esa katta savdogarlardan biriga aylandi.", "note": null},
{"num": 302, "time": "00:24:38,800 --> 00:24:43,720", "arabic": "إِنْ ذَابَ لِهَؤُلَاءِ أَوْ ذَابَ لِهَؤُلَاءِ فَمَا يَعُودُ عَلَيْنَا مِنْ ذَلِكَ؟", "segs": [{"ar": "إِنْ ذَابَ لِهَؤُلَاءِ أَوْ ذَابَ لِهَؤُلَاءِ", "uz": "Bularga tegishli bo'lsa ham, ularga tegishli bo'lsa ham,"}, {"ar": "فَمَا يَعُودُ عَلَيْنَا مِنْ ذَلِكَ؟", "uz": "bizga bundan nima foyda?"}], "full_uz": "Bularga tegishli bo'lsa ham, ularga tegishli bo'lsa ham, bizga bundan nima foyda?", "note": null},
{"num": 304, "time": "00:24:43,720 --> 00:24:52,960", "arabic": "رَحِمَ اللَّهُ شَفِيعًا، نِعْمَ الرَّجُلُ.", "segs": null, "full_uz": "Alloh Shafi'ga rahmat qilsin, qanday ham yaxshi odam edi.", "note": null},
{"num": 306, "time": "00:24:52,960 --> 00:25:03,740", "arabic": "لَوْلَا مَوْقِفُهُ مِنِ ابْنِ حَنْبَلٍ، مَنْ كَانَ يُصَدِّقُ أَنَّ رَجُلًا كَشَفِيعٍ سَيُلْقِي بِمَوَدَّتِهِ لِأَحْمَدَ بْنِ حَنْبَلٍ؟", "segs": [{"ar": "لَوْلَا مَوْقِفُهُ مِنِ ابْنِ حَنْبَلٍ،", "uz": "Uning Ibn Hanbalga bo'lgan pozitsiyasi bo'lmaganida,"}, {"ar": "مَنْ كَانَ يُصَدِّقُ أَنَّ رَجُلًا كَشَفِيعٍ", "uz": "Shafi'ga o'xshash odam Ahmad ibn"}, {"ar": "سَيُلْقِي بِمَوَدَّتِهِ لِأَحْمَدَ بْنِ حَنْبَلٍ؟", "uz": "Hanbalga bunday muhabbat ko'rsatishiga kim ishonardi?"}], "full_uz": "Uning Ibn Hanbalga bo'lgan pozitsiyasi bo'lmaganida, Shafi'ga o'xshash odam Ahmad ibn Hanbalga bunday muhabbat ko'rsatishiga kim ishonardi?", "note": null},
{"num": 309, "time": "00:25:03,740 --> 00:25:14,339", "arabic": "وَلَكِنْ لَا غَرْوَ إِذْ إِنَّهُ لَيْسَ وَحْدَهُ، غَفَرَ اللَّهُ لَهُ وَلَهُمْ.", "segs": [{"ar": "وَلَكِنْ لَا غَرْوَ إِذْ إِنَّهُ لَيْسَ وَحْدَهُ،", "uz": "Lekin bunda ajablanarli narsa yo'q, chunki u yolg'iz emas,"}, {"ar": "غَفَرَ اللَّهُ لَهُ وَلَهُمْ.", "uz": "Alloh unga va ularga mag'firat bersin."}], "full_uz": "Lekin bunda ajablanarli narsa yo'q, chunki u yolg'iz emas, Alloh unga va ularga mag'firat bersin.", "note": null},
{"num": 311, "time": "00:25:14,339 --> 00:25:23,839", "arabic": "السَّلَامُ عَلَيْكُمْ.", "segs": null, "full_uz": "Assalomu alaykum.", "note": null},
{"num": 312, "time": "00:25:23,839 --> 00:25:25,680", "arabic": "وَعَلَيْكُمُ السَّلَامُ وَرَحْمَةُ اللَّهِ.", "segs": null, "full_uz": "Va alaykum assalomu va rahmatullah.", "note": null},
{"num": 313, "time": "00:25:25,680 --> 00:25:26,579", "arabic": "السَّلَامُ عَلَيْكُمْ.", "segs": null, "full_uz": "Assalomu alaykum.", "note": null},
{"num": 314, "time": "00:25:26,579 --> 00:25:28,220", "arabic": "وَعَلَيْكُمُ السَّلَامُ وَرَحْمَةُ اللَّهِ.", "segs": null, "full_uz": "Va alaykum assalomu va rahmatullah.", "note": null},
{"num": 316, "time": "00:26:00,240 --> 00:26:14,480", "arabic": "الْحَيَاةُ صَعْبَةٌ بَعْدَكِ يَا خَالَةُ.", "segs": null, "full_uz": "Sizdan keyingi hayot qiyin, xolajon.", "note": null},
{"num": 317, "time": "00:26:14,480 --> 00:26:17,920", "arabic": "أَحْمَدُ اللَّهَ عَلَيْكَ يَا وَلَدِي.", "segs": null, "full_uz": "Sen uchun Allohga hamd aytaman, o'g'lim.", "note": null},
{"num": 318, "time": "00:26:30,240 --> 00:26:44,380", "arabic": "هَوِّنِي عَلَيْكِ يَا بُنَيَّتِي.", "segs": null, "full_uz": "Yengil ol, qizim.", "note": null},
{"num": 319, "time": "00:26:44,380 --> 00:26:58,140", "arabic": "تَعَالَيْ يَا سُعَادُ، النِّسَاءُ يَنْتَظِرْنَنَا فِي دَارِ الْعَزَاءِ، تَعَالَيْ.", "segs": null, "full_uz": "Kel, Su'od, ayollar bizni ta'ziya uyida kutishyapti, kel.", "note": null},
{"num": 322, "time": "00:27:00,240 --> 00:27:26,019", "arabic": "لَقَدْ عَادَتِ الْمِحْنَةُ أَشَدَّ وَطْأَةً مِنْ قَبْلُ أَيُّهَا الْإِخْوَةُ، لَقَدْ نَمَى إِلَيَّ...", "segs": [{"ar": "لَقَدْ عَادَتِ الْمِحْنَةُ أَشَدَّ وَطْأَةً مِنْ قَبْلُ أَيُّهَا الْإِخْوَةُ،", "uz": "Sinov ilgarigidan ham qattiqroq qaytdi, birodarlar,"}, {"ar": "لَقَدْ نَمَى إِلَيَّ...", "uz": "menga xabar yetib keldi..."}], "full_uz": "Sinov ilgarigidan ham qattiqroq qaytdi, birodarlar, menga xabar yetib keldi...", "note": null},
{"num": 324, "time": "00:27:26,019 --> 00:27:35,839", "arabic": "أَنَّ الْوَاثِقَ أَصْدَرَ أَوَامِرَهُ إِلَى وُلَاتِهِ فِي الْأَمْصَارِ كُلِّهَا عَلَى حَمْلِ الْعُلَمَاءِ عَلَى الْقَوْلِ بِخَلْقِ الْقُرْآنِ الْكَرِيمِ.", "segs": [{"ar": "أَنَّ الْوَاثِقَ أَصْدَرَ أَوَامِرَهُ إِلَى وُلَاتِهِ فِي الْأَمْصَارِ", "uz": "Vosiq barcha viloyatlardagi hokimlariga olimlarni Qur'oni Karimning"}, {"ar": "كُلِّهَا عَلَى حَمْلِ الْعُلَمَاءِ", "uz": "yaratilganligi haqida so'z aytishga"}, {"ar": "عَلَى الْقَوْلِ بِخَلْقِ الْقُرْآنِ الْكَرِيمِ.", "uz": "majburlash to'g'risida buyruq bergan."}], "full_uz": "Vosiq barcha viloyatlardagi hokimlariga olimlarni Qur'oni Karimning yaratilganligi haqida so'z aytishga majburlash to'g'risida buyruq bergan.", "note": null},
{"num": 326, "time": "00:27:35,839 --> 00:27:49,740", "arabic": "إِلَى مَتَى نَظَلُّ عَلَى هَذَا الْحَالِ؟ ظُهُورُنَا تَحْتَ السِّيَاطِ، وَرِقَابُنَا تَعْلُوهَا السُّيُوفُ، وَشُيُوخُنَا وَعُلَمَاؤُنَا إِمَّا مُطَارَدُونَ وَإِمَّا مَسْجُونُونَ.", "segs": [{"ar": "إِلَى مَتَى نَظَلُّ عَلَى هَذَا الْحَالِ؟ ظُهُورُنَا تَحْتَ السِّيَاطِ،", "uz": "Qachongacha shu holatda qolamiz? Orqalarimiz qamchi ostida, bo'ynimiz ustida qilichlar,"}, {"ar": "وَرِقَابُنَا تَعْلُوهَا السُّيُوفُ،", "uz": "shayxlarimiz va olimlarimiz"}, {"ar": "وَشُيُوخُنَا وَعُلَمَاؤُنَا إِمَّا مُطَارَدُونَ وَإِمَّا مَسْجُونُونَ.", "uz": "esa yo ta'qib qilinmoqda, yo qamoqda."}], "full_uz": "Qachongacha shu holatda qolamiz? Orqalarimiz qamchi ostida, bo'ynimiz ustida qilichlar, shayxlarimiz va olimlarimiz esa yo ta'qib qilinmoqda, yo qamoqda.", "note": null},
{"num": 331, "time": "00:27:49,740 --> 00:27:58,519", "arabic": "وَإِمَّا مُقِرُّونَ بِكَلِمَةِ الْكُفْرِ.", "segs": null, "full_uz": "Yoxud kufr so'zini tan olmoqdalar.", "note": null},
{"num": 333, "time": "00:27:58,519 --> 00:28:03,640", "arabic": "لَمْ أَقْصِدْ ذَلِكَ يَا ابْنَ مَعِينٍ.", "segs": null, "full_uz": "Buni nazarda tutmagan edim, Ibn Ma'in.", "note": null},
{"num": 334, "time": "00:28:03,640 --> 00:28:20,599", "arabic": "إِنْ لَمْ تَقُلْهَا أَنْتَ فَنَحْنُ أَقْرَرْنَا بِهَا يَا ابْنَ هَانِئٍ، أَجَلْ أَرْهَبَنَا الْخَوْفُ فَلَمْ نَثْبُتْ عَلَى الْحَقِّ، وَوَقَعْنَا فِي جُبِّ الضَّلَالَةِ وَالْبِدَعِ.", "segs": [{"ar": "إِنْ لَمْ تَقُلْهَا أَنْتَ", "uz": "Agar sen aytmasang ham,"}, {"ar": "فَنَحْنُ أَقْرَرْنَا بِهَا يَا ابْنَ هَانِئٍ،", "uz": "biz uni tan oldik, ey Ibn Hani. Ha,"}, {"ar": "أَجَلْ أَرْهَبَنَا الْخَوْفُ فَلَمْ نَثْبُتْ عَلَى الْحَقِّ،", "uz": "qo'rquv bizni qo'rqitdi, biz haq ustida sobit turmadik,"}, {"ar": "وَوَقَعْنَا فِي جُبِّ الضَّلَالَةِ وَالْبِدَعِ.", "uz": "va adashuv va bid'at chohiga tushib qoldik."}], "full_uz": "Agar sen aytmasang ham, biz uni tan oldik, ey Ibn Hani. Ha, qo'rquv bizni qo'rqitdi, biz haq ustida sobit turmadik, va adashuv va bid'at chohiga tushib qoldik.", "note": null},
{"num": 337, "time": "00:28:20,599 --> 00:28:34,479", "arabic": "وَاللَّهِ مَا قَصَدْتُ شَيْئًا، إِنَّمَا هُوَ حَنَقِي، حَنَقِي عَلَى مَنْ كَانَ السَّبَبَ فِيمَا نَحْنُ فِيهِ.", "segs": [{"ar": "وَاللَّهِ مَا قَصَدْتُ شَيْئًا،", "uz": "Vallohi, hech narsani nazarda tutmagan edim,"}, {"ar": "إِنَّمَا هُوَ حَنَقِي،", "uz": "bu faqat mening g'azabim,"}, {"ar": "حَنَقِي عَلَى مَنْ كَانَ السَّبَبَ فِيمَا نَحْنُ فِيهِ.", "uz": "biz tushib qolgan holatga sabab bo'lganlarga bo'lgan g'azabim."}], "full_uz": "Vallohi, hech narsani nazarda tutmagan edim, bu faqat mening g'azabim, biz tushib qolgan holatga sabab bo'lganlarga bo'lgan g'azabim.", "note": null},
{"num": 340, "time": "00:28:34,479 --> 00:28:38,439", "arabic": "لَا عَلَيْكَ يَا ابْنَ هَانِئٍ.", "segs": null, "full_uz": "Hech gap emas, Ibn Hani.", "note": null},
{"num": 341, "time": "00:28:38,439 --> 00:28:59,180", "arabic": "يَكْفِينِي مِنَ الْحَسَرَاتِ أَنْ أَخْسَرَ صَدِيقَ طُفُولَتِي وَصِبَايَ وَشَبَابِي، إِمَامَنَا أَحْمَدَ بْنَ حَنْبَلٍ، وَاللَّهِ إِنَّ صُدُودَهُ عَنِّي وَجَفَاءَهُ لِي كَانَ أَشَدَّ وَطْأَةً مِنْ سِيَاطِ أَمِيرِ الْمُؤْمِنِينَ عَلَى ظَهْرِي.", "segs": [{"ar": "يَكْفِينِي مِنَ الْحَسَرَاتِ أَنْ أَخْسَرَ صَدِيقَ طُفُولَتِي وَصِبَايَ وَشَبَابِي،", "uz": "Bolalik, o'smirlik va yoshlik do'stimni yo'qotishim menga achinish uchun yetarli,"}, {"ar": "إِمَامَنَا أَحْمَدَ بْنَ حَنْبَلٍ،", "uz": "imomimiz Ahmad ibn Hanbalni,"}, {"ar": "وَاللَّهِ إِنَّ صُدُودَهُ عَنِّي وَجَفَاءَهُ لِي", "uz": "vallohi, uning mendan yuz o'girishi va menga bo'lgan sovuqligi"}, {"ar": "كَانَ أَشَدَّ وَطْأَةً مِنْ سِيَاطِ أَمِيرِ الْمُؤْمِنِينَ عَلَى ظَهْرِي.", "uz": "mo'minlar amirining qamchisidan orqamga ko'ra ham og'irroq bo'ldi."}], "full_uz": "Bolalik, o'smirlik va yoshlik do'stim, imomimiz Ahmad ibn Hanbalni yo'qotishim menga achinish uchun yetarli. Vallohi, uning mendan yuz o'girishi va menga bo'lgan sovuqligi mo'minlar amirining qamchisidan orqamga ko'ra ham og'irroq bo'ldi.", "note": null},
{"num": 345, "time": "00:28:59,180 --> 00:29:09,700", "arabic": "لَوْ أَنَّهَا نَالَتْنِي، وَلَكِنْ مَاذَا أَقُولُ؟ حَسْبِيَ اللَّهُ وَنِعْمَ الْوَكِيلُ.", "segs": [{"ar": "لَوْ أَنَّهَا نَالَتْنِي،", "uz": "Qani edi u menga yetganida,"}, {"ar": "وَلَكِنْ مَاذَا أَقُولُ؟ حَسْبِيَ اللَّهُ وَنِعْمَ الْوَكِيلُ.", "uz": "lekin nima ham derdim? Alloh menga kifoya qiladi, U qanday ham yaxshi vakildir."}], "full_uz": "Qani edi u menga yetganida, lekin nima ham derdim? Alloh menga kifoya qiladi, U qanday ham yaxshi vakildir.", "note": null},
{"num": 348, "time": "00:29:09,700 --> 00:29:17,440", "arabic": "مَا بِكَ يَا أَبَا نَصْرٍ؟ لِمَاذَا هَذَا الشُّرُودُ؟", "segs": null, "full_uz": "Senga nima bo'ldi, Abu Nasr? Bu xayolparastlik nima uchun?", "note": null},
{"num": 350, "time": "00:29:20,440 --> 00:30:15,500", "arabic": "زَمَانُ الْكَلَامِ قَدِ انْتَهَى أَيُّهَا الْإِخْوَةُ، إِلَى مَتَى نَظَلُّ نَتَخَفَّى خَلْفَ أَصَابِعِنَا؟ وَنَحْنُ نَرَى أَهْلَ الْبِدَعِ وَالضَّلَالَةِ يَنْشُرُونَ ضَلَالَاتِهِمْ بِقُوَّةِ السُّلْطَانِ، إِلَى مَتَى نَظَلُّ هَكَذَا نَتَحَسَّرُ كَالنِّسَاءِ وَدِينُ اللَّهِ يُعْتَدَى عَلَيْهِ؟ إِلَى مَتَى تَسَعُنَا الْمَجَالِسُ وَلَا تَسَعُنَا سَاحَاتُ الْمَعَارِكِ؟ أَلَسْتُمْ مِنْ أَهْلِ الْعِلْمِ؟ أَلَيْسَتْ أَبْصَارُ النَّاسِ شَاخِصَةً إِلَيْكُمْ لِتَغْيِيرِ الْفَسَادِ الَّذِي بَدَأَ يَنْخُرُ دِينَكُمْ؟ أَمْ تُرِيدُونَ أَنْ يَنْهَضَ غَيْرُكُمْ لِيُعِزَّ الْإِسْلَامَ وَالْمُسْلِمِينَ؟", "segs": [{"ar": "زَمَانُ الْكَلَامِ قَدِ انْتَهَى أَيُّهَا الْإِخْوَةُ، إِلَى مَتَى نَظَلُّ نَتَخَفَّى خَلْفَ أَصَابِعِنَا؟", "uz": "Gapirish zamoni tugadi, birodarlar. Qachongacha barmoqlarimiz orqasida yashiringan bo'lib qolamiz?"}, {"ar": "وَنَحْنُ نَرَى أَهْلَ الْبِدَعِ وَالضَّلَالَةِ يَنْشُرُونَ ضَلَالَاتِهِمْ بِقُوَّةِ السُّلْطَانِ،", "uz": "Biz bid'at va adashuv ahlining sulton kuchi bilan o'z adashuvlarini tarqatganini ko'rib turibmiz-ku,"}, {"ar": "إِلَى مَتَى نَظَلُّ هَكَذَا نَتَحَسَّرُ كَالنِّسَاءِ وَدِينُ اللَّهِ يُعْتَدَى عَلَيْهِ؟", "uz": "qachongacha shunday ayollardek g'am chekib o'tiramiz, Allohning dini esa unga tajovuz qilinmoqda?"}, {"ar": "إِلَى مَتَى تَسَعُنَا الْمَجَالِسُ وَلَا تَسَعُنَا سَاحَاتُ الْمَعَارِكِ؟ أَلَسْتُمْ مِنْ أَهْلِ الْعِلْمِ؟", "uz": "qachongacha majlislar bizga yetadi-yu, jang maydonlari yetmaydi? Sizlar ilm ahlidan emasmisizlar?"}, {"ar": "أَلَيْسَتْ أَبْصَارُ النَّاسِ شَاخِصَةً إِلَيْكُمْ لِتَغْيِيرِ الْفَسَادِ الَّذِي بَدَأَ يَنْخُرُ دِينَكُمْ؟ أَمْ تُرِيدُونَ أَنْ يَنْهَضَ غَيْرُكُمْ لِيُعِزَّ الْإِسْلَامَ وَالْمُسْلِمِينَ؟", "uz": "odamlarning ko'zlari fasodni o'zgartirish uchun sizlarga qaratilmaganmi? Yoki boshqalar turishini xohlaysizlarmi?"}], "full_uz": "Gapirish zamoni tugadi, birodarlar. Qachongacha barmoqlarimiz orqasida yashiringan bo'lib qolamiz? Biz bid'at va adashuv ahlining sulton kuchi bilan o'z adashuvlarini tarqatganini ko'rib turibmiz-ku. Qachongacha shunday ayollardek g'am chekib o'tiramiz, Allohning dini esa unga tajovuz qilinmoqda? Qachongacha majlislar bizga yetadi-yu, jang maydonlari yetmaydi? Sizlar ilm ahlidan emasmisizlar? Odamlarning ko'zlari dinlariga kirib borgan fasodni o'zgartirish uchun sizlarga qaratilmaganmi? Yoki Islom va musulmonlarni aziz qilish uchun boshqalar turg'onini xohlaysizlarmi?", "note": null},
{"num": 362, "time": "00:30:15,500 --> 00:30:23,120", "arabic": "وَلَكِنْ مَا حِيلَتُنَا إِنْ كَانَ مَنْ تَوَلَّى هَذَا الْأَمْرَ هُوَ وَلِيُّ أَمْرِ الْمُسْلِمِينَ وَخَلِيفَتُهُمْ يَا أَبَا نَصْرٍ؟", "segs": [{"ar": "وَلَكِنْ مَا حِيلَتُنَا إِنْ كَانَ", "uz": "Lekin bu ishni boshlagan"}, {"ar": "مَنْ تَوَلَّى هَذَا الْأَمْرَ هُوَ", "uz": "kishi musulmonlarning rahbari va xalifasi bo'lsa,"}, {"ar": "وَلِيُّ أَمْرِ الْمُسْلِمِينَ وَخَلِيفَتُهُمْ يَا أَبَا نَصْرٍ؟", "uz": "bizning choramiz nima, Abu Nasr?"}], "full_uz": "Lekin bu ishni boshlagan kishi musulmonlarning rahbari va xalifasi bo'lsa, bizning choramiz nima, Abu Nasr?", "note": null},
{"num": 364, "time": "00:30:23,120 --> 00:30:24,240", "arabic": "تَعْسًا لَهُ.", "segs": null, "full_uz": "Unga halokat bo'lsin.", "note": null},
{"num": 365, "time": "00:30:24,240 --> 00:30:38,320", "arabic": "مَا أَصْبَحَ خَلِيفَةً إِلَّا بِنَا، وَنَحْنُ شُرَكَاءُ فِي إِثْمِهِ، نَشْرِ الْبِدَعِ، وَإِعْزَازِ أَهْلِ الضَّلَالَةِ، وَمُحَارَبَةِ أَهْلِ الْقُرْآنِ وَالْحَدِيثِ.", "segs": [{"ar": "مَا أَصْبَحَ خَلِيفَةً إِلَّا بِنَا،", "uz": "U faqat biz orqali xalifa bo'ldi,"}, {"ar": "وَنَحْنُ شُرَكَاءُ فِي إِثْمِهِ، نَشْرِ الْبِدَعِ،", "uz": "va biz uning gunohiga — bid'atlarni tarqatish, adashuv ahlini aziz qilish,"}, {"ar": "وَإِعْزَازِ أَهْلِ الضَّلَالَةِ، وَمُحَارَبَةِ أَهْلِ الْقُرْآنِ وَالْحَدِيثِ.", "uz": "va Qur'on va hadis ahliga qarshi urushishga — sherikmiz."}], "full_uz": "U faqat biz orqali xalifa bo'ldi, va biz uning gunohiga — bid'atlarni tarqatish, adashuv ahlini aziz qilish, va Qur'on va hadis ahliga qarshi urushishga — sherikmiz.", "note": null},
{"num": 370, "time": "00:30:38,319 --> 00:30:47,759", "arabic": "أَلَمْ يَقُلْ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ أَرَادَكُمْ عَلَى مَعْصِيَةٍ فَلَا تُطِيعُوهُ.", "segs": [{"ar": "أَلَمْ يَقُلْ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ", "uz": "Rasululloh (sollallohu alayhi va sallam): \"Kim sizni gunohga majburlasa,"}, {"ar": "وَسَلَّمَ: مَنْ أَرَادَكُمْ عَلَى مَعْصِيَةٍ فَلَا تُطِيعُوهُ.", "uz": "unga itoat qilmang\" demaganmidi?"}], "full_uz": "Rasululloh (sollallohu alayhi va sallam): \"Kim sizni gunohga majburlasa, unga itoat qilmang\" demaganmidi?", "note": "Payg'ambar (sav)ning gunohda itoat yo'qligi haqidagi hadisiga ishora (Sahih Buxoriy, Muslim)."},
{"num": 373, "time": "00:30:47,759 --> 00:30:53,619", "arabic": "وَنَحْنُ لَا نُطِيعُ عَلَى مَعْصِيَةٍ يَا أَبَا نَصْرٍ.", "segs": null, "full_uz": "Biz esa gunohda itoat qilmaymiz, Abu Nasr.", "note": null},
{"num": 374, "time": "00:30:53,619 --> 00:31:06,179", "arabic": "أَلَيْسَ الْأَمْرُ بِالْمَعْرُوفِ وَالنَّهْيُ عَنِ الْمُنْكَرِ فَرْضَ كِفَايَةٍ عَلَى الْمُسْلِمِينَ؟ إِنْ لَمْ يَقُمْ بِهِ بَعْضُهُمْ أَثِمَ الْجَمِيعُ.", "segs": [{"ar": "أَلَيْسَ الْأَمْرُ بِالْمَعْرُوفِ وَالنَّهْيُ عَنِ الْمُنْكَرِ", "uz": "Yaxshilikka buyurish va yomonlikdan qaytarish musulmonlarga farzi kifoya emasmi?"}, {"ar": "فَرْضَ كِفَايَةٍ عَلَى الْمُسْلِمِينَ؟ إِنْ لَمْ", "uz": "Agar ba'zilari uni bajarmasa,"}, {"ar": "يَقُمْ بِهِ بَعْضُهُمْ أَثِمَ الْجَمِيعُ.", "uz": "hammasi gunohkor bo'ladi."}], "full_uz": "Yaxshilikka buyurish va yomonlikdan qaytarish musulmonlarga farzi kifoya emasmi? Agar ba'zilari uni bajarmasa, hammasi gunohkor bo'ladi.", "note": null},
{"num": 377, "time": "00:31:06,180 --> 00:31:21,799", "arabic": "أَلَمْ تَسْمَعُوا قَوْلَ اللَّهِ تَعَالَى: وَلْتَكُنْ مِنْكُمْ أُمَّةٌ يَدْعُونَ إِلَى الْخَيْرِ وَيَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنْكَرِ وَأُولَئِكَ هُمُ الْمُفْلِحُونَ؟", "segs": [{"ar": "أَلَمْ تَسْمَعُوا قَوْلَ اللَّهِ تَعَالَى:", "uz": "Alloh taologa gapini eshitmadinglarmi: \"Sizlardan yaxshilikka chaqiruvchi,"}, {"ar": "وَلْتَكُنْ مِنْكُمْ أُمَّةٌ يَدْعُونَ إِلَى الْخَيْرِ", "uz": "ma'rufga buyuruvchi va munkardan"}, {"ar": "وَيَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنْكَرِ وَأُولَئِكَ هُمُ الْمُفْلِحُونَ؟", "uz": "qaytaruvchi bir jamoa bo'lsin, ana o'shalar najot topguvchilardir\"?"}], "full_uz": "Alloh taologa gapini eshitmadinglarmi: \"Sizlardan yaxshilikka chaqiruvchi, ma'rufga buyuruvchi va munkardan qaytaruvchi bir jamoa bo'lsin, ana o'shalar najot topguvchilardir\"?", "note": "Qur'on, Oli Imron surasi, 104-oyat."},
{"num": 381, "time": "00:31:21,799 --> 00:31:41,340", "arabic": "أَلَمْ يَقُلْ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ رَأَى مِنْكُمْ مُنْكَرًا فَلْيُغَيِّرْهُ بِيَدِهِ، فَإِنْ لَمْ يَسْتَطِعْ فَبِلِسَانِهِ، فَإِنْ لَمْ يَسْتَطِعْ فَبِقَلْبِهِ وَذَلِكَ أَضْعَفُ الْإِيمَانِ؟", "segs": [{"ar": "أَلَمْ يَقُلْ رَسُولُ اللَّهِ", "uz": "Rasululloh (sollallohu alayhi va sallam):"}, {"ar": "صَلَّى اللَّهُ عَلَيْهِ", "uz": "\"Sizlardan kim bir munkarni ko'rsa,"}, {"ar": "وَسَلَّمَ: مَنْ رَأَى مِنْكُمْ مُنْكَرًا فَلْيُغَيِّرْهُ بِيَدِهِ،", "uz": "uni qo'li bilan o'zgartirsin, agar qo'lidan kelmasa,"}, {"ar": "فَإِنْ لَمْ يَسْتَطِعْ فَبِلِسَانِهِ،", "uz": "tili bilan, agar u ham qo'lidan kelmasa,"}, {"ar": "فَإِنْ لَمْ يَسْتَطِعْ فَبِقَلْبِهِ وَذَلِكَ أَضْعَفُ الْإِيمَانِ؟", "uz": "qalbi bilan, va bu imonning eng zaifidir\" demaganmidi?"}], "full_uz": "Rasululloh (sollallohu alayhi va sallam): \"Sizlardan kim bir munkarni ko'rsa, uni qo'li bilan o'zgartirsin, agar qo'lidan kelmasa, tili bilan, agar u ham qo'lidan kelmasa, qalbi bilan, va bu imonning eng zaifidir\" demaganmidi?", "note": "Sahih Muslimdagi mashhur hadis."},
{"num": 388, "time": "00:31:41,340 --> 00:31:45,460", "arabic": "أَلَيْسَ لَنَا فِي إِنْكَارِ الْقَلْبِ مَنْدُوحَةٌ يَا أَبَا نَصْرٍ؟", "segs": null, "full_uz": "Qalb bilan inkor qilishda bizga kengchilik yo'qmi, Abu Nasr?", "note": null},
{"num": 389, "time": "00:31:46,900 --> 00:31:50,059", "arabic": "لَقَدْ تَجَاوَزَ الْأَمْرُ طَاقَةَ الْقَلْبِ يَا يَحْيَى.", "segs": null, "full_uz": "Ish qalb toqatidan oshib ketdi, ey Yahyo.", "note": null},
{"num": 390, "time": "00:31:50,059 --> 00:32:04,460", "arabic": "إِنْ سَكَتْنَا عَلَى الْبَاطِلِ أَكْثَرَ، انْتَشَرَ فَأَثِمْنَا جَمِيعًا وَهَلَكْنَا جَمِيعًا.", "segs": [{"ar": "إِنْ سَكَتْنَا عَلَى الْبَاطِلِ أَكْثَرَ،", "uz": "Agar botilga yana ham sukut qilsak, u tarqaladi,"}, {"ar": "انْتَشَرَ فَأَثِمْنَا جَمِيعًا وَهَلَكْنَا جَمِيعًا.", "uz": "va hammamiz gunohkor bo'lib, hammamiz halok bo'lamiz."}], "full_uz": "Agar botilga yana ham sukut qilsak, u tarqaladi, va hammamiz gunohkor bo'lib, hammamiz halok bo'lamiz.", "note": null},
{"num": 394, "time": "00:32:05,460 --> 00:32:19,319", "arabic": "أَنَا عَلَى يَقِينٍ أَنَّهُ لَمْ يُغَادِرْ بَغْدَادَ أَيُّهَا الْأَمِيرُ، لَكِنَّهُ لَيْسَ فِي دَارِهِمْ مُنْذُ ثَلَاثَةِ أَيَّامٍ.", "segs": [{"ar": "أَنَا عَلَى يَقِينٍ أَنَّهُ", "uz": "Men uning Bag'dodni tark etmaganiga ishonchim komil,"}, {"ar": "لَمْ يُغَادِرْ بَغْدَادَ أَيُّهَا الْأَمِيرُ،", "uz": "amir,"}, {"ar": "لَكِنَّهُ لَيْسَ فِي دَارِهِمْ مُنْذُ ثَلَاثَةِ أَيَّامٍ.", "uz": "lekin u uch kundan beri o'z uyida yo'q."}], "full_uz": "Men uning Bag'dodni tark etmaganiga ishonchim komil, amir, lekin u uch kundan beri o'z uyida yo'q.", "note": null},
{"num": 396, "time": "00:32:19,319 --> 00:32:31,400", "arabic": "لَسْتُ أَدْرِي، عُيُونُنَا لَمْ تَرَهُ يَخْرُجُ مِنَ الْمَدِينَةِ، كَمَا أَنَّهُ لَيْسَ عِنْدَ ابْنِهِ صَالِحٍ وَلَا عِنْدَ عَمِّهِ إِسْحَاقَ وَلَا عِنْدَ أَحَدٍ مِنْ طَلَبَتِهِ.", "segs": [{"ar": "لَسْتُ أَدْرِي،", "uz": "Bilmayman,"}, {"ar": "عُيُونُنَا لَمْ تَرَهُ يَخْرُجُ مِنَ الْمَدِينَةِ،", "uz": "ko'zchilarimiz uning shahardan chiqishini ko'rmadi, shuningdek,"}, {"ar": "كَمَا أَنَّهُ لَيْسَ عِنْدَ ابْنِهِ صَالِحٍ", "uz": "u o'g'li Solihning oldida ham,"}, {"ar": "وَلَا عِنْدَ عَمِّهِ إِسْحَاقَ وَلَا عِنْدَ أَحَدٍ مِنْ طَلَبَتِهِ.", "uz": "amakisi Ishoqning oldida ham, shogirdlaridan hech birining oldida ham emas."}], "full_uz": "Bilmayman, ko'zchilarimiz uning shahardan chiqishini ko'rmadi, shuningdek, u o'g'li Solihning oldida ham, amakisi Ishoqning oldida ham, shogirdlaridan hech birining oldida ham emas.", "note": null},
{"num": 398, "time": "00:32:31,400 --> 00:32:43,519", "arabic": "إِنْ كَانَ فِي بَغْدَادَ فَحَتْمًا سَنَعْرِفُ مَكَانَهُ.", "segs": null, "full_uz": "Agar u Bag'dodda bo'lsa, albatta uning qayerdaligini bilib olamiz.", "note": null},
{"num": 400, "time": "00:32:43,519 --> 00:32:53,820", "arabic": "وَأَنْتَ يَا ابْنَ السِّرَاجِ، قُلْتَ لِي إِنَّ لَدَيْكَ مَا تَقُولُهُ.", "segs": [{"ar": "وَأَنْتَ يَا ابْنَ السِّرَاجِ،", "uz": "Sen esa, Ibn Siroj,"}, {"ar": "قُلْتَ لِي إِنَّ لَدَيْكَ مَا تَقُولُهُ.", "uz": "menga aytadigan gaping bor deb aytding."}], "full_uz": "Sen esa, Ibn Siroj, menga aytadigan gaping bor deb aytding.", "note": null},
{"num": 402, "time": "00:32:53,820 --> 00:33:08,679", "arabic": "الْحَقُّ يَا مَوْلَايَ أَنَّ هَذَا الْخُزَاعِيَّ بَدَأَ يُثِيرُ شُكُوكًا كَثِيرَةً، وَأَحْسِبُ أَنَّهُ يُدَبِّرُ لِأَمْرٍ بِلَيْلٍ، لَكِنِّي لَمْ أَتَأَكَّدْ مِنْهُ بَعْدُ، لَيْتَهُ يَمْنَحُنِي سَبَبًا وَاحِدًا لِلْخَلَاصِ مِنْهُ.", "segs": [{"ar": "الْحَقُّ يَا مَوْلَايَ أَنَّ هَذَا الْخُزَاعِيَّ بَدَأَ يُثِيرُ شُكُوكًا كَثِيرَةً،", "uz": "Rostini aytsam, xo'jayinim, bu al-Xuzoiy ko'plab shubhalar uyg'otishni boshladi,"}, {"ar": "وَأَحْسِبُ أَنَّهُ يُدَبِّرُ لِأَمْرٍ بِلَيْلٍ،", "uz": "va menimcha, u tunda bir ishni rejalashtiryapti,"}, {"ar": "لَكِنِّي لَمْ أَتَأَكَّدْ مِنْهُ بَعْدُ،", "uz": "lekin buni hali aniqlamadim,"}, {"ar": "لَيْتَهُ يَمْنَحُنِي سَبَبًا وَاحِدًا لِلْخَلَاصِ مِنْهُ.", "uz": "qani edi, u menga undan qutulish uchun bitta bahona bersa edi."}], "full_uz": "Rostini aytsam, xo'jayinim, bu al-Xuzoiy ko'plab shubhalar uyg'otishni boshladi, va menimcha, u tunda bir ishni rejalashtiryapti, lekin buni hali aniqlamadim. Qani edi, u menga undan qutulish uchun bitta bahona bersa edi.", "note": null},
{"num": 407, "time": "00:33:08,679 --> 00:33:15,679", "arabic": "لَكِنَّنَا الْآنَ مَشْغُولُونَ بِغَيْرِهِ.", "segs": null, "full_uz": "Lekin biz hozir boshqasi bilan bandmiz.", "note": null},
{"num": 408, "time": "00:33:15,679 --> 00:33:22,740", "arabic": "إِيَّاكَ أَنْ تُغْضِيَ عَنْ نَاظِرِكَ، أَنَا لَا أُفَارِقُهُ.", "segs": null, "full_uz": "Ko'zingizni undan olmang, men undan ajralmayman.", "note": null},
{"num": 410, "time": "00:33:22,740 --> 00:33:24,500", "arabic": "كَظِلِّهِ يَا مَوْلَايَ، لَا تَقْلَقْ.", "segs": null, "full_uz": "Uning soyasidek, xo'jayinim, xavotir olmang.", "note": null},
{"num": 411, "time": "00:33:28,819 --> 00:34:01,480", "arabic": "أَيُّ رَجُلٍ أَنْتَ يَا ابْنَ حَنْبَلٍ؟ أَلَا تَنَامُ أَبَدًا يَا ابْنَ حَنْبَلٍ؟ مُنْذُ ثَلَاثَةِ أَيَّامٍ وَأَنَا أُجْهِدُ نَفْسِي حَتَّى أُجَارِيَكَ فَلَمْ أَسْتَطِعْ، لَا فِي الصِّيَامِ وَلَا فِي الْقِيَامِ.", "segs": [{"ar": "أَيُّ رَجُلٍ أَنْتَ يَا", "uz": "Qanaqa odamsan o'zi,"}, {"ar": "ابْنَ حَنْبَلٍ؟ أَلَا تَنَامُ", "uz": "ey Ibn Hanbal? Sen umuman uxlamaysanmi,"}, {"ar": "أَبَدًا يَا ابْنَ حَنْبَلٍ؟ مُنْذُ ثَلَاثَةِ أَيَّامٍ", "uz": "Ibn Hanbal? Uch kundan beri senga"}, {"ar": "وَأَنَا أُجْهِدُ نَفْسِي حَتَّى أُجَارِيَكَ فَلَمْ أَسْتَطِعْ،", "uz": "teng kelish uchun o'zimni majburlab kelaman,"}, {"ar": "لَا فِي الصِّيَامِ وَلَا فِي الْقِيَامِ.", "uz": "lekin uddasidan chiqolmayapman, na ro'zada, na tunda ibodatda."}], "full_uz": "Qanaqa odamsan o'zi, ey Ibn Hanbal? Sen umuman uxlamaysanmi, Ibn Hanbal? Uch kundan beri senga teng kelish uchun o'zimni majburlab kelaman, lekin uddasidan chiqolmayapman, na ro'zada, na tunda ibodatda.", "note": null},
{"num": 415, "time": "00:34:01,480 --> 00:34:04,419", "arabic": "لَا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا.", "segs": null, "full_uz": "Alloh birortasini toqatidan tashqari narsaga taklif qilmaydi.", "note": "Qur'on, Baqara surasi, 286-oyat."},
{"num": 416, "time": "00:34:04,419 --> 00:34:11,259", "arabic": "وَكَمَا قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ لِجَسَدِكَ عَلَيْكَ حَقًّا.", "segs": [{"ar": "وَكَمَا قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ", "uz": "Va Rasululloh (sollallohu alayhi va sallam) aytganidek: \"Albatta,"}, {"ar": "وَسَلَّمَ: إِنَّ لِجَسَدِكَ عَلَيْكَ حَقًّا.", "uz": "tanangning ham senga haqqi bor.\""}], "full_uz": "Va Rasululloh (sollallohu alayhi va sallam) aytganidek: \"Albatta, tanangning ham senga haqqi bor.\"", "note": "Payg'ambar (sav)ning Abdulloh ibn Amrga aytgan mashhur hadisiga ishora (Sahih Buxoriy)."},
{"num": 419, "time": "00:34:11,259 --> 00:34:17,679", "arabic": "لَمْ تَقُلْ لِي أَيْنَ سَنُلْقِي رَحْلَنَا غَدًا.", "segs": null, "full_uz": "Ertaga qayerda tunashimizni menga aytmading.", "note": null},
{"num": 420, "time": "00:34:17,679 --> 00:34:33,980", "arabic": "الْحَقُّ يَا عَمَّاهُ أَنَّنِي طَرَحْتُ الْأَمْرَ عَلَى أَهْلِكَ وَطُلَّابِكَ، فَلَمْ تَرُقْ لَهُمُ الْفِكْرَةُ، وَرَأَوْا أَنَّ بَقَاءَكَ عِنْدِي آمَنُ لَكَ.", "segs": [{"ar": "الْحَقُّ يَا عَمَّاهُ أَنَّنِي طَرَحْتُ الْأَمْرَ عَلَى أَهْلِكَ وَطُلَّابِكَ،", "uz": "Rostini aytsam, amakijon, bu masalani oilangiz va shogirdlaringizga qo'ydim,"}, {"ar": "فَلَمْ تَرُقْ لَهُمُ الْفِكْرَةُ،", "uz": "ularga fikr yoqmadi,"}, {"ar": "وَرَأَوْا أَنَّ بَقَاءَكَ عِنْدِي آمَنُ لَكَ.", "uz": "va sizning mening oldimda qolishingizni sizga xavfsizroq deb bilishdi."}], "full_uz": "Rostini aytsam, amakijon, bu masalani oilangiz va shogirdlaringizga qo'ydim, ularga fikr yoqmadi, va sizning mening oldimda qolishingizni sizga xavfsizroq deb bilishdi.", "note": null},
{"num": 423, "time": "00:34:33,980 --> 00:34:35,460", "arabic": "إِذَنْ فَلِمَ تَفْعَلُ؟", "segs": null, "full_uz": "Unda nega shunday qilyapsan?", "note": null},
{"num": 424, "time": "00:34:35,460 --> 00:34:48,599", "arabic": "أَنَا لَمْ أُصَدِّقْ أَنَّنِي رَأَيْتُكَ فِي دَارِي يَا أَبَا عَبْدِ اللَّهِ، وَأَنِّي لَا أَظُنُّ بِكَ أَنْ تَخْرُجَ مِنْهَا، فَكَيْفَ وَأَنْتَ لَمْ تَدْخُلْهَا إِلَّا مُنْذُ ثَلَاثَةِ أَيَّامٍ؟", "segs": [{"ar": "أَنَا لَمْ أُصَدِّقْ أَنَّنِي رَأَيْتُكَ فِي", "uz": "Sizni uyimda ko'rganimga hali ham ishonolmayapman,"}, {"ar": "دَارِي يَا أَبَا عَبْدِ اللَّهِ،", "uz": "ey Abu Abdulloh,"}, {"ar": "وَأَنِّي لَا أَظُنُّ بِكَ أَنْ تَخْرُجَ مِنْهَا،", "uz": "va undan chiqishingizni ham tasavvur qilolmayman,"}, {"ar": "فَكَيْفَ", "uz": "qanday bo'lsin,"}, {"ar": "وَأَنْتَ لَمْ تَدْخُلْهَا إِلَّا مُنْذُ ثَلَاثَةِ أَيَّامٍ؟", "uz": "siz uch kundan beri kirgansiz-ku?"}], "full_uz": "Sizni uyimda ko'rganimga hali ham ishonolmayapman, ey Abu Abdulloh, va undan chiqishingizni ham tasavvur qilolmayman, qanday bo'lsin, siz uch kundan beri kirgansiz-ku?", "note": null},
{"num": 427, "time": "00:34:48,599 --> 00:34:55,860", "arabic": "إِنْ فَعَلْتَ مَا أَمَرْتُكَ بِهِ أَخْبَرْتُكَ شَيْئًا سَيُفِيدُكَ.", "segs": null, "full_uz": "Agar buyurgan narsamni bajarsang, senga foydali bo'ladigan bir narsani aytib beraman.", "note": null},
{"num": 428, "time": "00:34:55,860 --> 00:34:58,660", "arabic": "مَا هُوَ؟", "segs": null, "full_uz": "Nima ekan?", "note": null},
{"num": 429, "time": "00:34:58,660 --> 00:35:02,260", "arabic": "افْعَلْ مَا أَمَرْتُكَ بِهِ أَوَّلًا وَسَأُخْبِرُكَ.", "segs": null, "full_uz": "Avval buyurganimni bajar, keyin senga aytib beraman.", "note": null},
{"num": 430, "time": "00:35:02,260 --> 00:35:06,380", "arabic": "لَكَ مَا أَرَدْتَ يَا أَبَا عَبْدِ اللَّهِ.", "segs": null, "full_uz": "Xohlaganingiz bo'ladi, ey Abu Abdulloh.", "note": null},
{"num": 433, "time": "00:36:04,380 --> 00:36:19,500", "arabic": "فَرَّجَ اللَّهُ كَرْبَكَ يَا أَحْمَدُ، فَوَاللَّهِ لَقَدْ ضَاقَتْ بِيَ الدُّنْيَا، وَسَكَنَتْنِي الْهُمُومُ مُنْذُ غَادَرْتَنِي، يَا رَبِّ فَرِّجْ.", "segs": [{"ar": "فَرَّجَ اللَّهُ كَرْبَكَ يَا أَحْمَدُ،", "uz": "Alloh sizning g'amingizni yorsin, ey Ahmad. Vallohi,"}, {"ar": "فَوَاللَّهِ لَقَدْ ضَاقَتْ بِيَ الدُّنْيَا،", "uz": "dunyo menga tor keldi,"}, {"ar": "وَسَكَنَتْنِي الْهُمُومُ مُنْذُ غَادَرْتَنِي، يَا رَبِّ فَرِّجْ.", "uz": "va siz meni tark etganingizdan beri g'amlar meni egalladi. Ey Robbim, yorib ber."}], "full_uz": "Alloh sizning g'amingizni yorsin, ey Ahmad. Vallohi, dunyo menga tor keldi, va siz meni tark etganingizdan beri g'amlar meni egalladi. Ey Robbim, yorib ber.", "note": null},
{"num": 438, "time": "00:36:19,500 --> 00:36:33,920", "arabic": "كُلُّنَا اسْتَغْرَبْنَا مِنْ سُرْعَةِ رَحِيلِكَ عَنْ دَارِ ابْنِ هَانِئٍ النَّيْسَابُورِيِّ يَا إِمَامُ، فَمَا سِرُّ ذَلِكَ؟", "segs": [{"ar": "كُلُّنَا اسْتَغْرَبْنَا مِنْ سُرْعَةِ رَحِيلِكَ عَنْ", "uz": "Hammamiz Ibn Hani an-Naysoburiyning uyidan tez ketganingizga hayron bo'ldik,"}, {"ar": "دَارِ ابْنِ هَانِئٍ النَّيْسَابُورِيِّ يَا إِمَامُ،", "uz": "Imom,"}, {"ar": "فَمَا سِرُّ ذَلِكَ؟", "uz": "buning siri nima edi?"}], "full_uz": "Hammamiz Ibn Hani an-Naysoburiyning uyidan tez ketganingizga hayron bo'ldik, Imom, buning siri nima edi?", "note": null},
{"num": 440, "time": "00:36:34,380 --> 00:36:39,539", "arabic": "وَأَنَا كُنْتُ أَكْثَرَ انْزِعَاجًا مِنْكُمْ وَاسْتِغْرَابًا أَيْضًا، وَلَكِنَّ الْإِمَامَ قَالَ لِي...", "segs": [{"ar": "وَأَنَا كُنْتُ أَكْثَرَ انْزِعَاجًا مِنْكُمْ وَاسْتِغْرَابًا أَيْضًا،", "uz": "Men ham sizlardan ko'ra ko'proq bezovta va hayron bo'lgan edim,"}, {"ar": "وَلَكِنَّ الْإِمَامَ قَالَ لِي...", "uz": "lekin Imom menga aytdi..."}], "full_uz": "Men ham sizlardan ko'ra ko'proq bezovta va hayron bo'lgan edim, lekin Imom menga aytdi...", "note": null},
{"num": 442, "time": "00:36:39,539 --> 00:36:47,200", "arabic": "افْعَلْ فَإِنْ فَعَلْتَ أَفَدْتُكَ، وَهَا أَنَا قَدْ فَعَلْتُ وَأَنْتَظِرُ مِنْهُ الْإِفَادَةَ.", "segs": [{"ar": "افْعَلْ فَإِنْ فَعَلْتَ أَفَدْتُكَ،", "uz": "\"Qil, agar qilsang,"}, {"ar": "وَهَا أَنَا قَدْ فَعَلْتُ وَأَنْتَظِرُ مِنْهُ الْإِفَادَةَ.", "uz": "senga foyda beraman\" dedi, va mana men qildim va undan foyda kutyapman."}], "full_uz": "\"Qil, agar qilsang, senga foyda beraman\" dedi, va mana men qildim va undan foyda kutyapman.", "note": null},
{"num": 445, "time": "00:36:47,200 --> 00:36:56,380", "arabic": "وَعَدْتَنِي يَا إِبْرَاهِيمُ فَوَفَيْتَ، وَسَأَفِي لَكَ أَنَا كَذَلِكَ، وَسَأُفِيدُكُمْ أَنْتُمْ أَيْضًا.", "segs": [{"ar": "وَعَدْتَنِي يَا إِبْرَاهِيمُ فَوَفَيْتَ،", "uz": "Menga va'da bergan eding, ey Ibrohim,"}, {"ar": "وَسَأَفِي لَكَ أَنَا كَذَلِكَ، وَسَأُفِيدُكُمْ أَنْتُمْ أَيْضًا.", "uz": "va va'dangga vafo qilding, men ham senga vafo qilaman, va sizlarga ham foyda beraman."}], "full_uz": "Menga va'da bergan eding, ey Ibrohim, va va'dangga vafo qilding, men ham senga vafo qilaman, va sizlarga ham foyda beraman.", "note": null},
{"num": 448, "time": "00:36:57,559 --> 00:37:01,340", "arabic": "اللَّهُمَّ لَا تَحْرِمْنَا فَضْلَ عَبْدِكَ ابْنِ حَنْبَلٍ. اللَّهُمَّ آمِينَ.", "segs": null, "full_uz": "Ey Alloh, bizni bandang Ibn Hanbalning fazlidan mahrum qilma. Ey Alloh, omin.", "note": null},
{"num": 451, "time": "00:37:01,340 --> 00:37:18,820", "arabic": "اخْتَفَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي الْغَارِ ثَلَاثَةَ أَيَّامٍ، ثُمَّ تَحَوَّلَ، وَلَيْسَ يَنْبَغِي أَنْ نَتَّبِعَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي الرَّخَاءِ وَنَتْرُكَهُ فِي الشِّدَّةِ.", "segs": [{"ar": "اخْتَفَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ", "uz": "Rasululloh (sollallohu alayhi va sallam)"}, {"ar": "وَسَلَّمَ فِي الْغَارِ ثَلَاثَةَ أَيَّامٍ،", "uz": "g'orda uch kun yashiringan,"}, {"ar": "ثُمَّ تَحَوَّلَ،", "uz": "so'ng joy"}, {"ar": "وَلَيْسَ يَنْبَغِي أَنْ نَتَّبِعَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ", "uz": "o'zgartirgan edi. Rasulullohga faqat farovonlikda ergashib,"}, {"ar": "وَسَلَّمَ فِي الرَّخَاءِ وَنَتْرُكَهُ فِي الشِّدَّةِ.", "uz": "qiyinchilikda tark etishimiz to'g'ri emas."}], "full_uz": "Rasululloh (sollallohu alayhi va sallam) g'orda uch kun yashiringan, so'ng joy o'zgartirgan edi. Rasulullohga faqat farovonlikda ergashib, qiyinchilikda tark etishimiz to'g'ri emas.", "note": "Payg'ambar (sav)ning Savr g'oridagi hijrat voqeasiga ishora."},
{"num": 455, "time": "00:37:18,820 --> 00:37:25,740", "arabic": "فَهَذِهِ فَائِدَةٌ، أَكْرِمْ بِهَا مِنْ فَائِدَةٍ.", "segs": null, "full_uz": "Mana bu foyda, qanday ham qadrli foyda.", "note": null},
{"num": 457, "time": "00:37:31,340 --> 00:37:45,320", "arabic": "السَّلَامُ عَلَيْكُمْ.", "segs": null, "full_uz": "Assalomu alaykum.", "note": null},
{"num": 459, "time": "00:37:45,320 --> 00:37:47,820", "arabic": "هَذِهِ لَكُمْ.", "segs": null, "full_uz": "Bu sizlarga.", "note": null},
{"num": 460, "time": "00:37:47,820 --> 00:37:51,280", "arabic": "لِمَ أَتْعَبْتَ نَفْسَكَ يَا وَلَدِي؟", "segs": null, "full_uz": "Nega o'zingni charchatding, o'g'lim?", "note": null},
{"num": 461, "time": "00:37:51,280 --> 00:37:52,760", "arabic": "فَفِي الدَّارِ مَا يَكْفِي.", "segs": null, "full_uz": "Uyda yetarlicha bor edi-ku.", "note": null},
{"num": 462, "time": "00:37:52,760 --> 00:37:55,039", "arabic": "فَضْلُ اللَّهِ عَلَيْنَا كَثِيرٌ يَا خَالَةُ.", "segs": null, "full_uz": "Allohning bizga fazli ko'p, xolajon.", "note": null},
{"num": 463, "time": "00:37:55,039 --> 00:37:56,800", "arabic": "أَيْنَ أَخِي عَبْدُ اللَّهِ؟", "segs": null, "full_uz": "Ukam Abdulloh qayerda?", "note": null},
{"num": 464, "time": "00:37:56,800 --> 00:37:57,600", "arabic": "إِنَّهُ نَائِمٌ.", "segs": null, "full_uz": "U uxlab yotibdi.", "note": null},
{"num": 465, "time": "00:37:57,600 --> 00:38:01,019", "arabic": "أَخْبِرْنِي كَيْفَ حَالُ أَبِيكَ؟", "segs": null, "full_uz": "Ayting-chi, dadangizning ahvoli qalay?", "note": null},
{"num": 466, "time": "00:38:01,019 --> 00:38:03,360", "arabic": "بِخَيْرٍ بِخَيْرٍ وَالْحَمْدُ لِلَّهِ.", "segs": null, "full_uz": "Yaxshi, yaxshi, alhamdulillah.", "note": null},
{"num": 467, "time": "00:38:03,360 --> 00:38:04,840", "arabic": "أَهُوَ فِي مَكَانٍ آمِنٍ؟", "segs": null, "full_uz": "U xavfsiz joydami?", "note": null},
{"num": 468, "time": "00:38:04,840 --> 00:38:07,900", "arabic": "إِنْ شَاءَ اللَّهُ يَا خَالَةُ، إِنْ شَاءَ اللَّهُ، لَا تَقْلَقِي.", "segs": [{"ar": "إِنْ شَاءَ اللَّهُ يَا خَالَةُ،", "uz": "Inshaalloh, xolajon,"}, {"ar": "إِنْ شَاءَ اللَّهُ، لَا تَقْلَقِي.", "uz": "inshaalloh, xavotir olmang."}], "full_uz": "Inshaalloh, xolajon, inshaalloh, xavotir olmang.", "note": null},
{"num": 469, "time": "00:38:07,900 --> 00:38:21,780", "arabic": "وَمَنْ لَدَيَّ سِوَى أَبِي عَبْدِ اللَّهِ حَتَّى لَا أَقْلَقَ عَلَيْهِ؟ أَبِي بِخَيْرٍ يَا خَالَةُ، تَطْمَئِنِّينَ؟", "segs": [{"ar": "وَمَنْ لَدَيَّ سِوَى أَبِي عَبْدِ اللَّهِ حَتَّى", "uz": "Abu Abdullohdan boshqa yana kimim borki,"}, {"ar": "لَا أَقْلَقَ عَلَيْهِ؟ أَبِي بِخَيْرٍ يَا خَالَةُ،", "uz": "unga xavotir olmasam? Dadam yaxshi, xolajon,"}, {"ar": "تَطْمَئِنِّينَ؟", "uz": "xotirjam bo'lasizmi?"}], "full_uz": "Abu Abdullohdan boshqa yana kimim borki, unga xavotir olmasam? Dadam yaxshi, xolajon, xotirjam bo'lasizmi?", "note": null},
{"num": 471, "time": "00:38:21,780 --> 00:38:27,900", "arabic": "ثُمَّ كَيْفَ تَقُولِينَ مَنْ لَدَيْكِ سِوَى أَبِي عَبْدِ اللَّهِ؟ مَاذَا عَنِّي وَعَنْ عَبْدِ اللَّهِ أَخِي؟", "segs": [{"ar": "ثُمَّ كَيْفَ تَقُولِينَ مَنْ لَدَيْكِ سِوَى", "uz": "Xo'sh, Abu Abdullohdan boshqa yana"}, {"ar": "أَبِي عَبْدِ اللَّهِ؟ مَاذَا عَنِّي", "uz": "kimim bor deb qanday aytasiz?"}, {"ar": "وَعَنْ عَبْدِ اللَّهِ أَخِي؟", "uz": "Men-chi, ukam Abdulloh-chi?"}], "full_uz": "Xo'sh, Abu Abdullohdan boshqa yana kimim bor deb qanday aytasiz? Men-chi, ukam Abdulloh-chi?", "note": null},
{"num": 473, "time": "00:38:31,019 --> 00:38:34,579", "arabic": "حَفِظَكُمُ اللَّهُ جَمِيعًا مِنْ كُلِّ سُوءٍ.", "segs": null, "full_uz": "Alloh hammangizni har qanday yomonlikdan asrasin.", "note": null},
{"num": 474, "time": "00:38:34,579 --> 00:38:37,880", "arabic": "كَيْفَ هِيَ زَوْجَتُكَ؟", "segs": null, "full_uz": "Xotiningizning ahvoli qalay?", "note": null},
{"num": 475, "time": "00:38:37,880 --> 00:38:39,900", "arabic": "بِخَيْرٍ، بِخَيْرٍ وَالْحَمْدُ لِلَّهِ.", "segs": null, "full_uz": "Yaxshi, yaxshi, alhamdulillah.", "note": null},
{"num": 476, "time": "00:38:39,900 --> 00:38:41,800", "arabic": "هَلْ شُفِيَتْ مِنَ الْمَغَصِ؟", "segs": null, "full_uz": "Ich og'rig'idan tuzalib qoldimi?", "note": null},
{"num": 477, "time": "00:38:41,800 --> 00:38:43,679", "arabic": "أَجَلْ، الْيَوْمَ أَحْسَنُ.", "segs": null, "full_uz": "Ha, bugun yaxshiroq.", "note": null},
{"num": 478, "time": "00:38:43,679 --> 00:38:48,719", "arabic": "وَلَوْلَا ذَلِكَ لَزَارَتْكِ أُمُّ الْفَضْلِ، وَلَكِنْ تَعْرِفِينَ مَرَضَهَا شَغَلَهَا.", "segs": null, "full_uz": "Agar shu bo'lmaganida, Umm al-Fazl sizni ziyorat qilgan bo'lardi, lekin bilasiz, uning kasali uni band qilib qo'ydi.", "note": null},
{"num": 480, "time": "00:38:48,719 --> 00:38:51,360", "arabic": "أَتَمَّ اللَّهُ شِفَاءَهَا يَا صَالِحُ.", "segs": null, "full_uz": "Alloh uning shifosini to'liq qilsin, Solih.", "note": null},
{"num": 481, "time": "00:38:51,360 --> 00:38:55,039", "arabic": "السَّلَامُ عَلَيْكُمْ.", "segs": null, "full_uz": "Assalomu alaykum.", "note": null},
{"num": 483, "time": "00:38:55,039 --> 00:39:21,239", "arabic": "قَدْ جَمَعْتُكُمُ الْيَوْمَ أَيُّهَا الْإِخْوَةُ لِأَمْرٍ جَلَلٍ، وَأَنْتُمْ أَكْثَرُ مَنْ أَثِقُ بِهِمْ مِنْ بَيْنِ فِتْيَانِ بَغْدَادَ وَرِجَالِهَا، الْغَيُورِينَ عَلَى دِينِهِمْ، الْحَرِيصِينَ عَلَى دِينِ الْحَقِّ وَأَهْلِ الْحَقِّ.", "segs": [{"ar": "قَدْ جَمَعْتُكُمُ الْيَوْمَ أَيُّهَا الْإِخْوَةُ لِأَمْرٍ جَلَلٍ،", "uz": "Sizlarni bugun katta bir ish uchun to'pladim, birodarlar,"}, {"ar": "وَأَنْتُمْ أَكْثَرُ مَنْ أَثِقُ بِهِمْ مِنْ بَيْنِ فِتْيَانِ بَغْدَادَ", "uz": "siz Bag'dodning yigitlari va erlari orasida men eng ko'p ishonadigan"}, {"ar": "وَرِجَالِهَا،", "uz": "kishilarsiz — dinlariga g'ayratli,"}, {"ar": "الْغَيُورِينَ عَلَى دِينِهِمْ،", "uz": "haq"}, {"ar": "الْحَرِيصِينَ عَلَى دِينِ الْحَقِّ وَأَهْلِ الْحَقِّ.", "uz": "dini va haq ahliga sodiq bo'lganlar."}], "full_uz": "Sizlarni bugun katta bir ish uchun to'pladim, birodarlar, siz Bag'dodning yigitlari va erlari orasida men eng ko'p ishonadigan kishilarsiz — dinlariga g'ayratli, haq dini va haq ahliga sodiq bo'lganlar.", "note": null},
{"num": 487, "time": "00:39:21,239 --> 00:39:23,539", "arabic": "نَحْنُ طَوْعُ بَنَانِكَ يَا إِمَامُ.", "segs": null, "full_uz": "Biz sizning ixtiyoringizdamiz, Imom.", "note": null},
{"num": 488, "time": "00:39:23,539 --> 00:39:36,539", "arabic": "أَيُّهَا الْإِخْوَةُ، إِنَّ هَذَا الرَّجُلَ قَدْ تَجَاوَزَ حَدَّهُ، وَخَانَ الْأَمَانَةَ الَّتِي فِي عُنُقِهِ، وَأَسَاءَ لِلْإِسْلَامِ وَالْمُسْلِمِينَ.", "segs": [{"ar": "أَيُّهَا الْإِخْوَةُ، إِنَّ هَذَا الرَّجُلَ قَدْ تَجَاوَزَ حَدَّهُ،", "uz": "Birodarlar, bu odam o'z chegarasidan chiqib ketdi,"}, {"ar": "وَخَانَ الْأَمَانَةَ الَّتِي فِي عُنُقِهِ،", "uz": "bo'ynidagi omonatga xiyonat qildi,"}, {"ar": "وَأَسَاءَ لِلْإِسْلَامِ وَالْمُسْلِمِينَ.", "uz": "va Islom va musulmonlarga zarar yetkazdi."}], "full_uz": "Birodarlar, bu odam o'z chegarasidan chiqib ketdi, bo'ynidagi omonatga xiyonat qildi, va Islom va musulmonlarga zarar yetkazdi.", "note": null},
{"num": 490, "time": "00:39:37,199 --> 00:39:41,539", "arabic": "أَعَلَّكَ تَقْصِدُ أَمِيرَ الْمُؤْمِنِينَ؟", "segs": null, "full_uz": "Mo'minlar amirini nazarda tutyapsizmi?", "note": null},
{"num": 491, "time": "00:39:42,480 --> 00:40:01,039", "arabic": "لَقَدْ زَيَّنَ الشَّيْطَانُ لِلْوَاثِقِ ضَلَالَاتِهِ، فَجَاهَرَ بِالْقَوْلِ بِخَلْقِ الْقُرْآنِ، وَأَنْكَرَ الصِّفَاتِ الَّتِي أَثْبَتَهَا اللَّهُ لِنَفْسِهِ وَأَثْبَتَهَا لَهُ رَسُولُهُ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، أَعُوذُ بِاللَّهِ مِنْ غَضَبِ اللَّهِ.", "segs": [{"ar": "لَقَدْ زَيَّنَ الشَّيْطَانُ لِلْوَاثِقِ ضَلَالَاتِهِ،", "uz": "Shayton Vosiqqa o'z adashuvlarini chiroyli qilib ko'rsatdi,"}, {"ar": "فَجَاهَرَ بِالْقَوْلِ بِخَلْقِ الْقُرْآنِ،", "uz": "u ochiqchasiga Qur'onning yaratilganligini aytdi,"}, {"ar": "وَأَنْكَرَ الصِّفَاتِ الَّتِي أَثْبَتَهَا اللَّهُ لِنَفْسِهِ وَأَثْبَتَهَا لَهُ رَسُولُهُ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ،", "uz": "va Alloh O'zi uchun isbotlagan hamda Rasuli unga isbotlagan sifatlarni inkor etdi,"}, {"ar": "أَعُوذُ بِاللَّهِ مِنْ غَضَبِ اللَّهِ.", "uz": "Allohning g'azabidan Allohga sig'inaman."}], "full_uz": "Shayton Vosiqqa o'z adashuvlarini chiroyli qilib ko'rsatdi, u ochiqchasiga Qur'onning yaratilganligini aytdi, va Alloh O'zi uchun isbotlagan hamda Uning Rasuli (sollallohu alayhi va sallam) unga isbotlagan sifatlarni inkor etdi. Allohning g'azabidan Allohga sig'inaman.", "note": null},
{"num": 497, "time": "00:40:01,039 --> 00:40:11,179", "arabic": "أَقَدْ عَاهَدْتُ اللَّهَ أَنْ أَتَصَدَّى لِهَذَا الرَّجُلِ وَبِدْعَتِهِ، فَأَكْشِفَ سَوْأَةَ اعْتِقَادِهِ الْفَاسِدِ.", "segs": [{"ar": "أَقَدْ عَاهَدْتُ اللَّهَ أَنْ أَتَصَدَّى لِهَذَا الرَّجُلِ وَبِدْعَتِهِ،", "uz": "Men Allohga bu odamga va uning bid'atiga qarshi turishga va uning"}, {"ar": "فَأَكْشِفَ سَوْأَةَ اعْتِقَادِهِ الْفَاسِدِ.", "uz": "buzuq e'tiqodining sharmandaligini ochishga ahd qildim."}], "full_uz": "Men Allohga bu odamga va uning bid'atiga qarshi turishga va uning buzuq e'tiqodining sharmandaligini ochishga ahd qildim.", "note": null},
{"num": 499, "time": "00:40:11,179 --> 00:40:23,300", "arabic": "فَمَنْ أَرَادَ مِنْكُمْ أَنْ يَكُونَ مَعِي فِي هَذَا الْأَمْرِ فَلْيَبْقَ جَالِسًا، وَمَنْ لَمْ يُرِدْ فَلْيَنْهَضْ وَيُغَادِرْنَا.", "segs": [{"ar": "فَمَنْ أَرَادَ مِنْكُمْ أَنْ يَكُونَ مَعِي فِي هَذَا الْأَمْرِ", "uz": "Kimki bu ishda men bilan bo'lishni istasa, o'tirgan holda qolsin,"}, {"ar": "فَلْيَبْقَ جَالِسًا،", "uz": "kimki istamasa,"}, {"ar": "وَمَنْ لَمْ يُرِدْ فَلْيَنْهَضْ وَيُغَادِرْنَا.", "uz": "tursin va bizni tark etsin."}], "full_uz": "Kimki bu ishda men bilan bo'lishni istasa, o'tirgan holda qolsin, kimki istamasa, tursin va bizni tark etsin.", "note": null},
{"num": 503, "time": "00:40:23,300 --> 00:40:27,900", "arabic": "وَلْيَكْتُمْ عَنْ عَوَامِّ النَّاسِ أَمْرًا.", "segs": null, "full_uz": "Va bu ishni omma xalqdan yashirsin.", "note": null},
{"num": 504, "time": "00:40:27,900 --> 00:40:39,180", "arabic": "كُلُّنَا مَعَكَ يَا إِمَامُ، وَسَنَكُونُ بِإِذْنِ اللَّهِ يَدَكَ حَتَّى نَنْتَصِرَ لِدِينِ اللَّهِ، كُلُّنَا مَعَكَ وَنُبَايِعُكَ.", "segs": [{"ar": "كُلُّنَا مَعَكَ يَا إِمَامُ،", "uz": "Hammamiz siz bilanmiz, Imom, va Alloh xohlasa,"}, {"ar": "وَسَنَكُونُ بِإِذْنِ اللَّهِ يَدَكَ حَتَّى نَنْتَصِرَ لِدِينِ اللَّهِ،", "uz": "Allohning diniga g'alaba qozongunimizcha sizning qo'lingiz bo'lamiz,"}, {"ar": "كُلُّنَا مَعَكَ وَنُبَايِعُكَ.", "uz": "hammamiz siz bilanmiz va sizga bay'at qilamiz."}], "full_uz": "Hammamiz siz bilanmiz, Imom, va Alloh xohlasa, Allohning diniga g'alaba qozongunimizcha sizning qo'lingiz bo'lamiz, hammamiz siz bilanmiz va sizga bay'at qilamiz.", "note": null},
{"num": 508, "time": "00:40:39,180 --> 00:40:45,680", "arabic": "وَلَكِنَّنَا كَمَا تَرَى يَا إِمَامُ قِلَّةٌ، وَلَنْ نَسْتَطِيعَ مُوَاجَهَةَ مَنْ طَغَى وَعَلَى الْعِبَادِ تَجَبَّرَ.", "segs": [{"ar": "وَلَكِنَّنَا كَمَا تَرَى يَا إِمَامُ قِلَّةٌ،", "uz": "Lekin, ko'rib turganingizdek, Imom, biz ozchilikmiz,"}, {"ar": "وَلَنْ نَسْتَطِيعَ مُوَاجَهَةَ مَنْ طَغَى وَعَلَى الْعِبَادِ تَجَبَّرَ.", "uz": "va oshkora zulm qilib, bandalarga zo'ravonlik qilgan kishiga qarshi tura olmaymiz."}], "full_uz": "Lekin, ko'rib turganingizdek, Imom, biz ozchilikmiz, va oshkora zulm qilib, bandalarga zo'ravonlik qilgan kishiga qarshi tura olmaymiz.", "note": null},
{"num": 510, "time": "00:40:45,680 --> 00:40:50,680", "arabic": "وَأَنَا لَمْ أَقُلِ احْمِلُوا سُيُوفَكُمْ وَاخْرُجُوا قَاتِلُوهُ.", "segs": null, "full_uz": "Men sizlarga qilichlaringizni ko'tarib, chiqib uni o'ldiring demadim.", "note": null},
{"num": 513, "time": "00:40:51,220 --> 00:40:52,680", "arabic": "فَمَاذَا نَفْعَلُ إِذَنْ؟", "segs": null, "full_uz": "Unda nima qilamiz?", "note": null},
{"num": 514, "time": "00:40:53,300 --> 00:41:07,200", "arabic": "لَقَدْ أَصْبَحْنَا عَلَى يَقِينٍ أَنَّ ابْنَ حَنْبَلٍ مَا زَالَ فِي بَغْدَادَ أَيُّهَا الْأَمِيرُ.", "segs": [{"ar": "لَقَدْ أَصْبَحْنَا عَلَى يَقِينٍ أَنَّ ابْنَ", "uz": "Ibn Hanbal hali ham Bag'dodda"}, {"ar": "حَنْبَلٍ مَا زَالَ فِي بَغْدَادَ أَيُّهَا الْأَمِيرُ.", "uz": "ekaniga ishonchimiz komil bo'ldi, amir."}], "full_uz": "Ibn Hanbal hali ham Bag'dodda ekaniga ishonchimiz komil bo'ldi, amir.", "note": null},
{"num": 515, "time": "00:41:07,200 --> 00:41:15,220", "arabic": "أَمَّا أَنَا فَقَدْ أَخْبَرَنِي قَلْبِي بِذَلِكَ قَبْلَ أَنْ يُخْبِرَنِي بِهِ جَوَاسِيسُكَ يَا أَبَا عَبْدِ اللَّهِ.", "segs": [{"ar": "أَمَّا أَنَا", "uz": "Menga esa"}, {"ar": "فَقَدْ أَخْبَرَنِي قَلْبِي بِذَلِكَ قَبْلَ أَنْ", "uz": "buni josuslaring xabar berishidan oldin qalbim xabar bergan edi,"}, {"ar": "يُخْبِرَنِي بِهِ جَوَاسِيسُكَ يَا أَبَا عَبْدِ اللَّهِ.", "uz": "ey Abu Abdulloh."}], "full_uz": "Menga esa buni josuslaring xabar berishidan oldin qalbim xabar bergan edi, ey Abu Abdulloh.", "note": null},
{"num": 516, "time": "00:41:15,220 --> 00:41:25,920", "arabic": "وَلَكِنْ لَيْسَ هَذَا هُوَ الْمُهِمَّ. أَجَلْ، الْمُهِمُّ أَنْ نَعْرِفَ أَيْنَ هُوَ، أَيْنَ يَخْتَبِئُ.", "segs": [{"ar": "وَلَكِنْ لَيْسَ هَذَا هُوَ الْمُهِمَّ. أَجَلْ،", "uz": "Lekin muhimi bu emas. Ha,"}, {"ar": "الْمُهِمُّ أَنْ نَعْرِفَ أَيْنَ هُوَ، أَيْنَ يَخْتَبِئُ.", "uz": "muhimi uning qayerdaligini, qayerda yashirinayotganini bilishdir."}], "full_uz": "Lekin muhimi bu emas. Ha, muhimi uning qayerdaligini, qayerda yashirinayotganini bilishdir.", "note": null},
{"num": 518, "time": "00:41:25,920 --> 00:41:36,320", "arabic": "لَوْ فَتَّشَ حَرَسُ أَمِيرِ الْمُؤْمِنِينَ بُيُوتَ أَصْحَابِ ابْنِ حَنْبَلٍ، لَوَجَدُوهُ حَتْمًا عِنْدَ أَحَدِهِمْ.", "segs": [{"ar": "لَوْ فَتَّشَ حَرَسُ أَمِيرِ الْمُؤْمِنِينَ بُيُوتَ أَصْحَابِ ابْنِ حَنْبَلٍ،", "uz": "Agar mo'minlar amirining qorovullari Ibn Hanbalning safdoshlarining uylarini tekshirsalar,"}, {"ar": "لَوَجَدُوهُ حَتْمًا عِنْدَ أَحَدِهِمْ.", "uz": "albatta ulardan birining oldida uni topgan bo'lardilar."}], "full_uz": "Agar mo'minlar amirining qorovullari Ibn Hanbalning safdoshlarining uylarini tekshirsalar, albatta ulardan birining oldida uni topgan bo'lardilar.", "note": null},
{"num": 521, "time": "00:41:36,320 --> 00:41:40,639", "arabic": "هَذَا مَوْطِنُ خِلَافٍ. فَأَمِيرُ الْمُؤْمِنِينَ لَنْ يُصْدِرَ قَرَارًا مِثْلَ هَذَا.", "segs": [{"ar": "هَذَا مَوْطِنُ خِلَافٍ.", "uz": "Bu ixtilofli"}, {"ar": "فَأَمِيرُ الْمُؤْمِنِينَ لَنْ يُصْدِرَ قَرَارًا مِثْلَ هَذَا.", "uz": "masala. Mo'minlar amiri bunday qaror chiqarmaydi."}], "full_uz": "Bu ixtilofli masala. Mo'minlar amiri bunday qaror chiqarmaydi.", "note": null},
{"num": 522, "time": "00:41:40,639 --> 00:41:52,840", "arabic": "فَإِنْ لَمْ نَعْثُرْ عَلَيْهِ نَحْنُ، فَلْنَسْتَطِعْ حَمْلَ أَمِيرِ الْمُؤْمِنِينَ عَلَى الْقَبْضِ عَلَيْهِ، يَجِبُ أَنْ تَسْبِقَ أَيْدِينَا يَدَ الْوَاثِقِ.", "segs": [{"ar": "فَإِنْ لَمْ نَعْثُرْ عَلَيْهِ نَحْنُ،", "uz": "Agar biz uni topa olmasak,"}, {"ar": "فَلْنَسْتَطِعْ حَمْلَ أَمِيرِ الْمُؤْمِنِينَ عَلَى الْقَبْضِ عَلَيْهِ،", "uz": "mo'minlar amirini uni qo'lga olishga undashimiz kerak,"}, {"ar": "يَجِبُ أَنْ تَسْبِقَ أَيْدِينَا يَدَ الْوَاثِقِ.", "uz": "bizning qo'llarimiz Vosiqning qo'lidan oldinda bo'lishi shart."}], "full_uz": "Agar biz uni topa olmasak, mo'minlar amirini uni qo'lga olishga undashimiz kerak, bizning qo'llarimiz Vosiqning qo'lidan oldinda bo'lishi shart.", "note": null},
{"num": 525, "time": "00:41:52,840 --> 00:41:58,639", "arabic": "هَلْ عَجَزَ جَوَاسِيسُنَا أَنْ يَعْرِفُوا مَكَانَ رَجُلٍ مِثْلِ ابْنِ حَنْبَلٍ؟", "segs": [{"ar": "هَلْ عَجَزَ جَوَاسِيسُنَا أَنْ يَعْرِفُوا", "uz": "Josuslarimiz Ibn Hanbalga o'xshash"}, {"ar": "مَكَانَ رَجُلٍ مِثْلِ ابْنِ حَنْبَلٍ؟", "uz": "odamning joyini bilishga ojiz qolishdimi?"}], "full_uz": "Josuslarimiz Ibn Hanbalga o'xshash odamning joyini bilishga ojiz qolishdimi?", "note": null},
{"num": 526, "time": "00:41:58,639 --> 00:42:01,980", "arabic": "عُيُونُنَا لَا تَنَامُ يَا بَدْرُ.", "segs": null, "full_uz": "Ko'zlarimiz uxlamaydi, Badr.", "note": null},
{"num": 527, "time": "00:42:01,980 --> 00:42:12,380", "arabic": "فَقَدْ نَمَى إِلَيْنَا أَنَّهُ يُمْكِنُ أَنْ يَكُونَ عِنْدَ الْمَرُّوذِيِّ أَوِ النَّيْسَابُورِيِّ، وَلَكِنَّنَا لَسْنَا عَلَى يَقِينٍ.", "segs": [{"ar": "فَقَدْ نَمَى إِلَيْنَا أَنَّهُ يُمْكِنُ أَنْ", "uz": "Bizga xabar yetib keldi,"}, {"ar": "يَكُونَ عِنْدَ الْمَرُّوذِيِّ أَوِ النَّيْسَابُورِيِّ،", "uz": "u al-Marroziy yoki an-Naysoburiyning oldida bo'lishi mumkin,"}, {"ar": "وَلَكِنَّنَا لَسْنَا عَلَى يَقِينٍ.", "uz": "lekin biz aniq ishonchimiz komil emas."}], "full_uz": "Bizga xabar yetib keldi, u al-Marroziy yoki an-Naysoburiyning oldida bo'lishi mumkin, lekin biz aniq ishonchimiz komil emas.", "note": null},
{"num": 529, "time": "00:42:12,380 --> 00:42:22,960", "arabic": "إِنْ بَقِيَ فِي بَغْدَادَ فَسَيَقَعُ مَهْمَا طَالَ الزَّمَنُ، وَإِنْ خَرَجَ مِنْهَا فَإِلَى حَيْثُ أَلْقَتْ...", "segs": [{"ar": "إِنْ بَقِيَ فِي بَغْدَادَ فَسَيَقَعُ مَهْمَا طَالَ الزَّمَنُ،", "uz": "Agar Bag'dodda qolsa, vaqt qanchalik cho'zilmasin, qo'limizga tushadi,"}, {"ar": "وَإِنْ خَرَجَ مِنْهَا فَإِلَى حَيْثُ أَلْقَتْ...", "uz": "agar undan chiqsa, u yerda qayerga tashlasa..."}], "full_uz": "Agar Bag'dodda qolsa, vaqt qanchalik cho'zilmasin, qo'limizga tushadi, agar undan chiqsa, u yerda qayerga tashlasa...", "note": null},
{"num": 532, "time": "00:42:22,960 --> 00:42:32,160", "arabic": "مَا بِكَ سَاهِيًا شَارِدًا يَا ابْنَ سِرَاجٍ؟ حَقًّا مَا الَّذِي يَشْغَلُكَ؟", "segs": [{"ar": "مَا بِكَ سَاهِيًا شَارِدًا يَا ابْنَ", "uz": "Senga nima bo'ldi, xayolparast, ey Ibn Siroj?"}, {"ar": "سِرَاجٍ؟ حَقًّا مَا الَّذِي يَشْغَلُكَ؟", "uz": "Rostini ayt, seni nima band qilyapti?"}], "full_uz": "Senga nima bo'ldi, xayolparast, ey Ibn Siroj? Rostini ayt, seni nima band qilyapti?", "note": null},
{"num": 534, "time": "00:42:32,160 --> 00:42:37,539", "arabic": "يَشْغَلُنِي أَحْمَدُ بْنُ نَصْرٍ الْخُزَاعِيُّ، وَمَا بِهِ هَذَا الْمَأْفُونُ.", "segs": null, "full_uz": "Meni Ahmad ibn Nasr al-Xuzoiy band qilyapti, va bu ahmoqning holi.", "note": null},
{"num": 536, "time": "00:42:37,539 --> 00:42:49,159", "arabic": "لَا أَدْرِي، وَلَكِنَّنِي أَشْعُرُ أَنَّهُ يُحَضِّرُ لِدَاهِيَةٍ، قَدْ حَاوَلْتُ أَنْ أَعْرِفَ الْأَمْرَ، أَخْشَى أَنْ يَكُونَ قَدْ خَبَرَنِي فَلَنْ يُطْلِعَنِي عَلَى الْخَبَرِ.", "segs": [{"ar": "لَا أَدْرِي، وَلَكِنَّنِي أَشْعُرُ أَنَّهُ يُحَضِّرُ لِدَاهِيَةٍ،", "uz": "Bilmayman, lekin u bir yovuzlikka tayyorgarlik ko'rayotganini his qilyapman,"}, {"ar": "قَدْ حَاوَلْتُ أَنْ أَعْرِفَ الْأَمْرَ،", "uz": "ishni bilishga harakat qildim,"}, {"ar": "أَخْشَى أَنْ يَكُونَ قَدْ خَبَرَنِي فَلَنْ يُطْلِعَنِي عَلَى الْخَبَرِ.", "uz": "u meni sinab bilib olgan bo'lishidan qo'rqaman, shuning uchun xabarni menga oshkor qilmaydi."}], "full_uz": "Bilmayman, lekin u bir yovuzlikka tayyorgarlik ko'rayotganini his qilyapman. Ishni bilishga harakat qildim, u meni sinab bilib olgan bo'lishidan qo'rqaman, shuning uchun xabarni menga oshkor qilmaydi.", "note": null},
{"num": 541, "time": "00:42:49,159 --> 00:42:55,239", "arabic": "وَكَيْفَ عَرَفْتَ أَنَّهُ يَشُقُّ بِكَ؟ إِنَّهُ يَكْتُمُ عَنِّي أَحَادِيثَهُ أَمَامَ أَصْحَابِهِ.", "segs": [{"ar": "وَكَيْفَ عَرَفْتَ أَنَّهُ يَشُقُّ بِكَ؟ إِنَّهُ", "uz": "Sen buni qayerdan bildingki, u sen bilan qiyinchilikda?"}, {"ar": "يَكْتُمُ عَنِّي أَحَادِيثَهُ أَمَامَ أَصْحَابِهِ.", "uz": "U safdoshlari oldida o'z suhbatlarini mendan yashiradi."}], "full_uz": "Sen buni qayerdan bildingki, u sen bilan qiyinchilikda? U safdoshlari oldida o'z suhbatlarini mendan yashiradi.", "note": null},
{"num": 543, "time": "00:42:55,239 --> 00:43:02,519", "arabic": "وَغَيْرَ مَرَّةٍ اسْتَأْذَنْتُ لِلدُّخُولِ عَلَيْهِ فَلَمْ يَأْذَنْ لِي، عَلَى الرَّغْمِ مِنْ أَنِّي أَعْلَمُ أَنَّ عِنْدَهُ بَعْضَ الرِّجَالِ.", "segs": [{"ar": "وَغَيْرَ مَرَّةٍ اسْتَأْذَنْتُ لِلدُّخُولِ عَلَيْهِ فَلَمْ يَأْذَنْ لِي،", "uz": "Bir necha marta uning oldiga kirishga ruxsat so'radim,"}, {"ar": "عَلَى الرَّغْمِ مِنْ أَنِّي", "uz": "lekin u menga ruxsat bermadi,"}, {"ar": "أَعْلَمُ أَنَّ عِنْدَهُ بَعْضَ الرِّجَالِ.", "uz": "garchi uning oldida ba'zi odamlar borligini bilsam ham."}], "full_uz": "Bir necha marta uning oldiga kirishga ruxsat so'radim, lekin u menga ruxsat bermadi, garchi uning oldida ba'zi odamlar borligini bilsam ham.", "note": null},
{"num": 546, "time": "00:43:02,519 --> 00:43:07,279", "arabic": "أَيَّ سُوءٍ تَتَفَوَّهُ بِهِ يَا ابْنَ سِرَاجٍ؟", "segs": null, "full_uz": "Qanday yomonlikni aytmoqchisan, Ibn Siroj?", "note": null},
{"num": 547, "time": "00:43:07,279 --> 00:43:11,279", "arabic": "أَلَمْ أَقُلْ لَكَ إِنَّ هَذَا الْخُزَاعِيَّ دَاهِيَةٌ فَاحْذَرْهُ؟", "segs": null, "full_uz": "Senga bu al-Xuzoiy bir yovuz balo, undan ehtiyot bo'l demaganmidim?", "note": null}
];

